return ['domain'=>'brikpanel','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'nl_NL','project-id-version'=>'BrikPanel','pot-creation-date'=>'2026-07-18T11:11:32+00:00','po-revision-date'=>'2026-06-17','x-generator'=>'Claude (BrikPanel auto-translation)','messages'=>['BrikPanel: WooCommerce Admin Dashboard Theme'=>'BrikPanel: WooCommerce Admin Dashboard-thema','Beautiful and modern Shopify-style WooCommerce admin panel & dashboard, fully free, forever.'=>'Mooi en modern WooCommerce-adminpaneel en -dashboard in Shopify-stijl, volledig gratis, voor altijd.','Brksoft'=>'Brksoft','https://brksoft.com/'=>'https://brksoft.com/','WooCommerce is not active on this site, so BrikPanel features are disabled here. Activate WooCommerce to enable BrikPanel.'=>'WooCommerce is niet actief op deze site, dus BrikPanel-functies zijn hier uitgeschakeld. Activeer WooCommerce om BrikPanel in te schakelen.','%d hidden notice'=>'%d verborgen melding' . "\0" . '%d verborgen meldingen','Other plugins and themes posted these notices. BrikPanel keeps them hidden, click to show.'=>'Andere plugins en thema\'s hebben deze meldingen geplaatst. BrikPanel houdt ze verborgen, klik om ze te tonen.','Settings'=>'Instellingen','Ad Platforms integration'=>'Advertentieplatforms-integratie','Pull daily ad spend from Google Ads and Meta Ads to calculate true ROAS and Net Profit on the dashboard. Currently in beta. Turn it off below to hide the admin page and stop all background sync jobs. Your connections stay saved.'=>'Haal dagelijkse advertentie-uitgaven op uit Google Ads en Meta Ads om de echte ROAS en nettowinst op het dashboard te berekenen. Momenteel in bèta. Schakel het hieronder uit om de beheerpagina te verbergen en alle achtergrondsynchronisaties te stoppen. Uw verbindingen blijven opgeslagen.','Enable Ad Platforms integration'=>'Advertentieplatforms-integratie inschakelen','When on, the Ad Platforms admin menu, daily sync, and dashboard ROAS / Net Profit cards are active. When off, the module is dormant: no menu item, no scheduled sync, no dashboard cards.'=>'Indien aan zijn het Advertentieplatforms-adminmenu, de dagelijkse synchronisatie en de ROAS / Nettowinst-kaarten op het dashboard actief. Indien uit is de module slapend: geen menu-item, geen geplande synchronisatie, geen dashboardkaarten.','Integrations'=>'Integraties','Beta'=>'Bèta','ROAS'=>'ROAS','Revenue / Ad spend'=>'Omzet / Advertentie-uitgaven','Ad currency differs from store'=>'Advertentievaluta verschilt van de winkel','Google Ads connection was revoked for security. Please reconnect.'=>'Google Ads-verbinding is om veiligheidsredenen ingetrokken. Maak opnieuw verbinding.','Not connected to Google Ads.'=>'Niet verbonden met Google Ads.','The BrikPanel proxy returned an unverifiable response and was rejected.'=>'De BrikPanel-proxy gaf een niet-verifieerbaar antwoord en werd geweigerd.','Request to Google Ads failed after retries.'=>'Verzoek aan Google Ads mislukte na meerdere pogingen.','Meta Ads connection was revoked for security. Please reconnect.'=>'Meta Ads-verbinding is om veiligheidsredenen ingetrokken. Maak opnieuw verbinding.','Not connected to Meta Ads.'=>'Niet verbonden met Meta Ads.','Request to Meta Ads failed after retries.'=>'Verzoek aan Meta Ads mislukte na meerdere pogingen.','Permission denied.'=>'Toegang geweigerd.','Unknown platform.'=>'Onbekend platform.','This connection is not available yet, it is pending platform approval.'=>'Deze verbinding is nog niet beschikbaar, ze wacht op goedkeuring van het platform.','Could not reach the BrikPanel proxy. Please try again in a moment.'=>'Kon de BrikPanel-proxy niet bereiken. Probeer het zo meteen opnieuw.','Could not start OAuth: proxy returned an error.'=>'Kon OAuth niet starten: proxy retourneerde een fout.','Disconnected.'=>'Verbinding verbroken.','OAuth session expired. Please try connecting again.'=>'OAuth-sessie verlopen. Probeer opnieuw verbinding te maken.','Unknown platform in OAuth state.'=>'Onbekend platform in OAuth-status.','OAuth callback was for a different user. Aborted.'=>'OAuth-callback was voor een andere gebruiker. Geannuleerd.','Could not reach the BrikPanel proxy.'=>'Kon de BrikPanel-proxy niet bereiken.','OAuth redemption failed. Please try connecting again.'=>'OAuth-inwisseling mislukt. Probeer opnieuw verbinding te maken.','Could not save tokens. Please try again.'=>'Kon tokens niet opslaan. Probeer het opnieuw.','Google Ads connected.'=>'Google Ads verbonden.','Meta Ads connected.'=>'Meta Ads verbonden.','Ad Platforms'=>'Advertentieplatforms','Beta feature'=>'Bètafunctie','Connecting…'=>'Verbinden…','Disconnect this platform? Your synced spend data will be deleted.'=>'Verbinding met dit platform verbreken? Uw gesynchroniseerde uitgavendata worden verwijderd.','Syncing…'=>'Synchroniseren…','Sync queued. Refresh the page in a moment.'=>'Synchronisatie in wachtrij. Vernieuw de pagina zo meteen.','Saved.'=>'Opgeslagen.','Loading accounts…'=>'Accounts laden…','No ad accounts found for this connection.'=>'Geen advertentieaccounts gevonden voor deze verbinding.','Something went wrong. Please try again.'=>'Er is iets misgegaan. Probeer het opnieuw.','No errors logged.'=>'Geen fouten geregistreerd.','Connected'=>'Verbonden','Not connected'=>'Niet verbonden','Pick a primary account first.'=>'Kies eerst een primair account.','Manager'=>'Manager','Loading history… %1$d of %2$d 90-day chunks done'=>'Geschiedenis laden… %1$d van %2$d delen van 90 dagen voltooid','Just now'=>'Zojuist','Google Ads'=>'Google Ads','Meta Ads'=>'Meta Ads','Loading imported data…'=>'Geïmporteerde gegevens laden…','No spend data imported yet. It appears here once the first sync or backfill completes.'=>'Nog geen uitgavengegevens geïmporteerd. Ze verschijnen hier zodra de eerste synchronisatie of aanvulling is voltooid.','Could not load imported data.'=>'Kon de geïmporteerde gegevens niet laden.','Account %s'=>'Account %s','%1$s to %2$s'=>'%1$s tot %2$s','%s days with spend'=>'%s dagen met uitgaven','Total spend'=>'Totale uitgaven','Impressions'=>'Vertoningen','Clicks'=>'Klikken','Avg CTR'=>'Gem. CTR','Avg CPC'=>'Gem. CPC','Avg CPM'=>'Gem. CPM','Month'=>'Maand','Spend'=>'Uitgaven','CTR'=>'CTR','CPC'=>'CPC','Days'=>'Dagen','All time'=>'Gehele periode','Connect this platform first.'=>'Verbind eerst dit platform.','Pick an account before saving.'=>'Kies een account voordat u opslaat.','Account saved. Loading 3 years of history in the background. Refresh the page in a few minutes to see it.'=>'Account opgeslagen. 3 jaar geschiedenis wordt op de achtergrond geladen. Vernieuw de pagina over een paar minuten om het te zien.','Account saved.'=>'Account opgeslagen.','Synced %1$d row(s) across %2$d day(s).'=>'%1$d rij(en) gesynchroniseerd over %2$d dag(en).','Ad spend daily sync'=>'Dagelijkse synchronisatie advertentie-uitgaven','Pulls yesterday plus the last 7 days of spend from each connected ad platform.'=>'Haalt gisteren plus de laatste 7 dagen aan uitgaven op van elk verbonden advertentieplatform.','Ad spend backfill chunk'=>'Advertentie-uitgaven backfill-deel','One 90-day slice of the initial historical pull when an ad platform is first connected.'=>'Eén deel van 90 dagen van de initiële historische ophaaltaak wanneer een advertentieplatform voor het eerst wordt verbonden.','Not connected.'=>'Niet verbonden.','Pending Google approval'=>'Wacht op goedkeuring van Google','Google Ads needs to approve our API access before this connection can go live. It will be enabled automatically once approved. No action is needed from you.'=>'Google Ads moet onze API-toegang goedkeuren voordat deze verbinding actief kan worden. Ze wordt automatisch ingeschakeld zodra ze is goedgekeurd. U hoeft niets te doen.','Connect Google Ads'=>'Verbinden met Google Ads','Pending Meta approval'=>'Wacht op goedkeuring van Meta','Meta needs to review our app before this connection can go live. It will be enabled automatically once approved. No action is needed from you.'=>'Meta moet onze app beoordelen voordat deze verbinding actief kan worden. Ze wordt automatisch ingeschakeld zodra ze is goedgekeurd. U hoeft niets te doen.','Connect Meta Ads'=>'Verbinden met Meta Ads','Coming soon'=>'Binnenkort beschikbaar','BrikPanel will request read-only access to your Google Ads accounts. We only pull total daily spend, impressions and clicks. No campaign management.'=>'BrikPanel vraagt alleen-lezen toegang tot uw Google Ads-accounts. We halen alleen de totale dagelijkse uitgaven, vertoningen en klikken op. Geen campagnebeheer.','BrikPanel will request read-only access (ads_read) to your Meta ad accounts. We only pull total daily spend, impressions and clicks.'=>'BrikPanel vraagt alleen-lezen-toegang (ads_read) tot uw Meta-advertentieaccounts. Wij halen alleen de dagelijkse totale uitgaven, impressies en klikken op.','Connected as'=>'Verbonden als','(email not shared)'=>'(e-mail niet gedeeld)','Primary ad account'=>'Primair advertentieaccount','BrikPanel pulls spend from this one account. To switch later, choose another from the list and click Save.'=>'BrikPanel haalt uitgaven op van dit ene account. Om later te wisselen, kiest u een ander uit de lijst en klikt u op Opslaan.','Click "Load accounts" to choose…'=>'Klik op "Accounts laden" om te kiezen…','Load accounts'=>'Accounts laden','Save'=>'Opslaan','Manager (MCC) account ID (optional)'=>'Manager (MCC) account-ID (optioneel)','Only fill in if you access the chosen account through a Google Ads manager. Digits only, no dashes.'=>'Vul alleen in als u het gekozen account benadert via een Google Ads-manager. Alleen cijfers, geen streepjes.','Last successful sync'=>'Laatste succesvolle synchronisatie','ago'=>'geleden','(last attempt failed, check the error log)'=>'(laatste poging mislukt, controleer het foutenlogboek)','Sync now'=>'Nu synchroniseren','Re-authorize'=>'Opnieuw autoriseren','Disconnect'=>'Verbinding verbreken','Connect Google Ads and Meta Ads so BrikPanel can show real ROAS and Net Profit on the dashboard.'=>'Verbind Google Ads en Meta Ads zodat BrikPanel echte ROAS en Nettowinst op het dashboard kan tonen.','Pulls daily total spend, impressions and clicks from one Google Ads account.'=>'Haalt dagelijkse totale uitgaven, impressies en klikken op van één Google Ads-account.','Pulls daily total spend, impressions and clicks from one Meta ad account (Facebook + Instagram).'=>'Haalt dagelijkse totale uitgaven, impressies en klikken op van één Meta-advertentieaccount (Facebook + Instagram).','Imported spend data'=>'Geïmporteerde uitgavengegevens','Everything BrikPanel has pulled so far, broken down by month. This is the raw data behind the dashboard ROAS and Net Profit figures.'=>'Alles wat BrikPanel tot nu toe heeft opgehaald, uitgesplitst per maand. Dit zijn de ruwe gegevens achter de ROAS- en nettowinstcijfers op het dashboard.','Refresh'=>'Vernieuwen','How it works'=>'Hoe het werkt','Connect each platform once. Tokens are encrypted on this server and never leave it.'=>'Verbind elk platform één keer. Tokens worden op deze server versleuteld en verlaten deze nooit.','On first connect, the last 3 years of daily spend are loaded in the background (90-day chunks every 30 seconds).'=>'Bij de eerste verbinding worden de laatste 3 jaar aan dagelijkse uitgaven op de achtergrond geladen (delen van 90 dagen elke 30 seconden).','After that, the last 7 days are refreshed once per day to capture late corrections.'=>'Daarna worden de laatste 7 dagen één keer per dag vernieuwd om late correcties vast te leggen.','Spend is stored in the ad account currency. The dashboard shows ad-currency totals next to your store revenue so you can compare them directly.'=>'Uitgaven worden opgeslagen in de valuta van het advertentieaccount. Het dashboard toont totalen in de advertentievaluta naast uw winkelomzet, zodat u ze direct kunt vergelijken.','Recent errors'=>'Recente fouten','Last 50 entries from the sync log. Token values are redacted before storage.'=>'Laatste 50 vermeldingen uit het synchronisatielogboek. Tokenwaarden worden geredigeerd voor opslag.','View log'=>'Logboek bekijken','Clear log'=>'Logboek wissen','System default'=>'Systeemstandaard','Appearance'=>'Weergave','Customize how the BrikPanel admin interface looks. Changes apply to dashboard, products, orders, coupons, segments, the top bar, sidebar, and the modern login page. The rest of WordPress admin is untouched.'=>'Pas aan hoe de BrikPanel-admininterface eruitziet. Wijzigingen gelden voor dashboard, producten, bestellingen, kortingsbonnen, segmenten, de bovenbalk, zijbalk en de moderne inlogpagina. De rest van de WordPress-admin blijft ongewijzigd.','Interface font'=>'Interfacelettertype','Pick the typeface used across BrikPanel. "System default" stays on your operating system\'s native font (no external request). Other choices load a single Google Fonts stylesheet with display: swap.'=>'Kies het lettertype dat in heel BrikPanel wordt gebruikt. "Systeemstandaard" blijft het oorspronkelijke lettertype van uw besturingssysteem (geen externe aanvraag). Andere keuzes laden één Google Fonts-stylesheet met display: swap.','Accent color'=>'Accentkleur','Primary color used for buttons, focus rings, toggles, and active highlights. The BrikPanel default is a near-black gray (#303030); pick anything you like.'=>'Primaire kleur die wordt gebruikt voor knoppen, focusringen, schakelaars en actieve markeringen. De BrikPanel-standaard is een bijna zwart grijs (#303030); kies wat u maar wilt.','Sidebar icon style'=>'Stijl van de zijbalkpictogrammen','Choose how the sidebar menu icons look. "Solid" uses the original filled icons (matching Shopify\'s admin). "Line" uses a thinner outline set for a lighter look.'=>'Kies hoe de pictogrammen in het zijbalkmenu eruitzien. "Gevuld" gebruikt de oorspronkelijke gevulde pictogrammen (net als de Shopify-beheeromgeving). "Lijn" gebruikt een dunnere contourset voor een lichter uiterlijk.','Solid (filled, original)'=>'Gevuld (origineel)','Line (thin outline)'=>'Lijn (dunne contour)','Custom brand logo'=>'Aangepast merklogo','Replace the BrikPanel mark in the admin top bar and on the modern login page with your own logo. Pick an image from your media library, or paste an external image URL to load it from a CDN. The logo applies as soon as it is set; use Remove to go back to the default BrikPanel icon and your site name. When a URL is set it takes priority over the media library pick. PNG or SVG with a transparent background gives the cleanest result. Recommended size: 256×256 px or wider.'=>'Vervang het BrikPanel-merkteken in de beheerbalk en op de moderne inlogpagina door je eigen logo. Kies een afbeelding uit je mediabibliotheek of plak de URL van een externe afbeelding om die vanaf een CDN te laden. Het logo wordt toegepast zodra het is ingesteld; gebruik Verwijderen om terug te gaan naar het standaard BrikPanel-pictogram en je sitenaam. Als er een URL is ingesteld, heeft die voorrang op de keuze uit de mediabibliotheek. Een PNG of SVG met een transparante achtergrond geeft het strakste resultaat. Aanbevolen formaat: 256×256 px of groter.','Custom CSS'=>'Aangepaste CSS','Add your own CSS to fine-tune the BrikPanel interface — change button colors, backgrounds, spacing, and more. Your rules load last, so they override the built-in styles. Tip: prefix your selectors with a BrikPanel class (for example .brikpanel-dashboard, .brikpanel-topbar, .brikpanel-pe) so the changes stay inside BrikPanel and leave the rest of the admin untouched.'=>'Voeg uw eigen CSS toe om de BrikPanel-interface te verfijnen: wijzig knopkleuren, achtergronden, witruimte en meer. Uw regels worden als laatste geladen, dus ze overschrijven de ingebouwde stijlen. Tip: laat uw selectors beginnen met een BrikPanel-klasse (bijvoorbeeld .brikpanel-dashboard, .brikpanel-topbar, .brikpanel-pe) zodat de wijzigingen binnen BrikPanel blijven en de rest van het beheer onaangeroerd laten.','No logo selected'=>'Geen logo geselecteerd','Replace logo'=>'Logo vervangen','Select logo'=>'Logo selecteren','Remove'=>'Verwijderen','Or load from an image URL (CDN)'=>'Of laden vanaf een afbeeldings-URL (CDN)','Select brand logo'=>'Merklogo selecteren','Use this image'=>'Gebruik deze afbeelding','Store Health'=>'Winkelgezondheid','BrikControl scans your store in the background and flags issues, like products missing images, from the topbar shield, a dashboard banner, and its own Store Health page. Turn it off to hide all of that and stop the scheduled scans. Your latest results stay saved, so turning it back on restores them.'=>'BrikControl scant uw winkel op de achtergrond en signaleert problemen, zoals producten zonder afbeelding, via het schild in de bovenbalk, een dashboardbanner en een eigen pagina Winkelgezondheid. Schakel het uit om dat alles te verbergen en de geplande scans te stoppen. Uw laatste resultaten blijven opgeslagen, dus weer inschakelen herstelt ze.','Enable Store Health (BrikControl)'=>'Winkelgezondheid inschakelen (BrikControl)','When on, the Store Health page, topbar shield, dashboard banner and daily background scans are active. When off, the entire module is dormant: no menu item, no topbar icon, no banner, and no scheduled scans.'=>'Indien ingeschakeld zijn de pagina Winkelgezondheid, het schild in de bovenbalk, de dashboardbanner en de dagelijkse achtergrondscans actief. Indien uitgeschakeld is de hele module slapend: geen menu-item, geen pictogram in de bovenbalk, geen banner en geen geplande scans.','Product Image Health'=>'Productafbeeldingsgezondheid','Scanning… %1$s / %2$s products'=>'Scannen… %1$s / %2$s producten','No product images found yet.'=>'Nog geen productafbeeldingen gevonden.','%1$s%% oversized (%2$s of %3$s) · %4$s%% modern format'=>'%1$s%% te groot (%2$s van %3$s) · %4$s%% modern formaat','Add product images to start the health check.'=>'Voeg productafbeeldingen toe om de gezondheidscontrole te starten.','%1$s product images are larger than 1 MB. Modern formats (WebP / AVIF) cover %2$s%% of your library. Missing files: %3$s.'=>'%1$s productafbeeldingen zijn groter dan 1 MB. Moderne formaten (WebP / AVIF) bestrijken %2$s%% van uw bibliotheek. Ontbrekende bestanden: %3$s.','No products yet — nothing to check.'=>'Nog geen producten — niets te controleren.','Add at least one published product to enable image health checks.'=>'Voeg minstens één gepubliceerd product toe om afbeeldingsgezondheidscontroles in te schakelen.','Install %s to compress images and convert to WebP/AVIF automatically.'=>'Installeer %s om afbeeldingen automatisch te comprimeren en te converteren naar WebP/AVIF.','Install plugin'=>'Plugin installeren','%1$s product images (%2$s%%) are larger than 1 MB. These slow down your product pages and hurt SEO. Compress them to under 200 KB where possible.'=>'%1$s productafbeeldingen (%2$s%%) zijn groter dan 1 MB. Deze vertragen uw productpagina\'s en schaden SEO. Comprimeer ze waar mogelijk tot onder de 200 KB.','Only %s%% of your product images use WebP / AVIF. Modern formats are 30–50%% smaller than JPEG/PNG with no visible quality loss.'=>'Slechts %s%% van uw productafbeeldingen gebruikt WebP / AVIF. Moderne formaten zijn 30–50%% kleiner dan JPEG/PNG zonder zichtbaar kwaliteitsverlies.','%s product images point to files that no longer exist on disk. Re-upload them or detach the missing media references.'=>'%s productafbeeldingen verwijzen naar bestanden die niet meer op schijf bestaan. Upload ze opnieuw of koppel de ontbrekende mediareferenties los.','Your product images are well-optimised. Keep an eye on this metric as you upload new products.'=>'Uw productafbeeldingen zijn goed geoptimaliseerd. Houd deze metric in de gaten terwijl u nieuwe producten uploadt.','BrikControl: Full Health Scan'=>'BrikControl: Volledige gezondheidsscan','Runs every BrikControl check and writes results to the dashboard.'=>'Voert elke BrikControl-controle uit en schrijft de resultaten naar het dashboard.','BrikControl: Scan Batch'=>'BrikControl: Scanbatch','Processes a single batch of a long-running BrikControl check.'=>'Verwerkt één batch van een langlopende BrikControl-controle.','Rescan now'=>'Nu opnieuw scannen','Scan queued — refreshing…'=>'Scan in wachtrij — vernieuwen…','Could not start scan.'=>'Kon scan niet starten.','Not scanned yet'=>'Nog niet gescand','Scanning in background…'=>'Scannen op achtergrond…','just now'=>'zojuist','Scanning {cursor} / {total} products…'=>'{cursor} / {total} producten scannen…','All checks passing'=>'Alle controles geslaagd','Open Store Health'=>'Winkelgezondheid openen','Last scan'=>'Laatste scan','Scanning…'=>'Scannen…','%s min ago'=>'%s min geleden' . "\0" . '%s min geleden','%s h ago'=>'%s u geleden' . "\0" . '%s u geleden','%s d ago'=>'%s d geleden' . "\0" . '%s d geleden','You do not have permission to access this page.'=>'U heeft geen toestemming om deze pagina te openen.','Not scanned yet — run a scan to see results.'=>'Nog niet gescand — voer een scan uit om resultaten te zien.','%s critical store health issue'=>'%s kritiek winkelgezondheidsprobleem' . "\0" . '%s kritieke winkelgezondheidsproblemen','%s store health warning'=>'%s winkelgezondheidswaarschuwing' . "\0" . '%s winkelgezondheidswaarschuwingen','Store health: all checks passing'=>'Winkelgezondheid: alle controles geslaagd','Open full report'=>'Volledig rapport openen','Run a scan to see store health checks.'=>'Voer een scan uit om winkelgezondheidscontroles te zien.','%s critical store health issue detected'=>'%s kritiek winkelgezondheidsprobleem gedetecteerd' . "\0" . '%s kritieke winkelgezondheidsproblemen gedetecteerd','Open the BrikControl report to see what to fix and which plugins can help.'=>'Open het BrikControl-rapport om te zien wat u moet repareren en welke plugins kunnen helpen.','View report'=>'Rapport bekijken','Dismiss for 7 days'=>'Negeren voor 7 dagen','A scan is already running.'=>'Er wordt al een scan uitgevoerd.','Action Scheduler is unavailable.'=>'Action Scheduler is niet beschikbaar.','Scan queued.'=>'Scan in wachtrij.','A scan is already in the queue.'=>'Er staat al een scan in de wachtrij.','Missing dismiss target.'=>'Doel voor negeren ontbreekt.','Invalid nonce.'=>'Ongeldige nonce.','Last scan: %s'=>'Laatste scan: %s','No scan completed yet.'=>'Nog geen scan voltooid.','Scan now'=>'Nu scannen','Critical'=>'Kritiek','Warnings'=>'Waarschuwingen','OK'=>'OK','Pending'=>'In afwachting','Scanning your store…'=>'Uw winkel scannen…','No checks registered yet. Once the first scan finishes, you will see results here.'=>'Nog geen controles geregistreerd. Zodra de eerste scan is voltooid, ziet u hier de resultaten.','Warning'=>'Waarschuwing','Health score'=>'Gezondheidsscore','Active optimizer plugins:'=>'Actieve optimalisatieplugins:','Open'=>'Open','Total images'=>'Totaal aantal afbeeldingen','Over 1 MB'=>'Groter dan 1 MB','WebP / AVIF'=>'WebP / AVIF','JPEG / PNG'=>'JPEG / PNG','Missing files'=>'Ontbrekende bestanden','Largest images (top 10)'=>'Grootste afbeeldingen (top 10)','Image'=>'Afbeelding','Size'=>'Grootte','Format'=>'Formaat','Action'=>'Actie','(no title)'=>'(geen titel)','Scanned %s'=>'Gescand %s','BrikMentor'=>'BrikMentor','Email automation for your store: abandoned cart recovery, win-back and post-purchase flows, AI campaigns. A premium companion plugin by the BrikPanel team.'=>'E-mailautomatisering voor je winkel: herstel van verlaten winkelwagens, terugwin- en na-aankoopstromen, AI-campagnes. Een premium aanvullende plugin van het BrikPanel-team.','BrikMentor is installed and active on this store.'=>'BrikMentor is geïnstalleerd en actief in deze winkel.','Open BrikMentor settings'=>'Instellingen van BrikMentor openen','You need the "install plugins" permission to set up BrikMentor. Ask a site administrator.'=>'Je hebt de rechten om plugins te installeren nodig om BrikMentor in te stellen. Vraag een sitebeheerder om hulp.','BrikMentor is installed but not active yet.'=>'BrikMentor is geïnstalleerd, maar nog niet actief.','Activate BrikMentor'=>'BrikMentor activeren','Enter the license key from your brksoft.com purchase. The plugin will be downloaded, installed and activated, and setup will continue with your license already in place.'=>'Voer de licentiesleutel van je aankoop op brksoft.com in. De plugin wordt gedownload, geïnstalleerd en geactiveerd, en het instellen gaat verder met je licentie al ingevuld.','License key'=>'Licentiesleutel','Install & Activate'=>'Installeren en activeren','Enter your license key first.'=>'Voer eerst je licentiesleutel in.','Installing… this can take up to a minute.'=>'Bezig met installeren… dit kan tot een minuut duren.','Activating…'=>'Bezig met activeren…','You do not have permission to activate plugins.'=>'Je hebt geen rechten om plugins te activeren.','BrikMentor activated. Opening setup…'=>'BrikMentor geactiveerd. Het instellen wordt geopend…','You do not have permission to install plugins.'=>'Je hebt geen rechten om plugins te installeren.','Could not create a temporary file.'=>'Er kon geen tijdelijk bestand worden aangemaakt.','This license key is not valid. Check the key from your brksoft.com purchase email and try again.'=>'Deze licentiesleutel is niet geldig. Controleer de sleutel in je aankoopmail van brksoft.com en probeer het opnieuw.','The download service could not be reached. Please try again in a few minutes.'=>'De downloadservice was niet bereikbaar. Probeer het over een paar minuten opnieuw.','Installation failed.'=>'Installatie mislukt.','Installed, but activation failed: %s'=>'Geïnstalleerd, maar activeren is mislukt: %s','BrikMentor installed and activated. Opening setup…'=>'BrikMentor geïnstalleerd en geactiveerd. Het instellen wordt geopend…','Opening secure checkout…'=>'Bezig met openen van de beveiligde afrekenpagina…','Your browser blocked the checkout window — click to open it.'=>'Je browser heeft het afrekenvenster geblokkeerd. Klik om het te openen.','Open checkout'=>'Afrekenen openen','Waiting for your payment…'=>'Wachten op je betaling…','Still waiting. Finish checkout in the other tab, or open it again.'=>'Nog steeds aan het wachten. Rond het afrekenen af op het andere tabblad, of open het opnieuw.','Payment received. Setting up BrikMentor…'=>'Betaling ontvangen. BrikMentor wordt ingesteld…','Downloading and installing BrikMentor…'=>'BrikMentor wordt gedownload en geïnstalleerd…','Activating your license…'=>'Je licentie wordt geactiveerd…','All set! Opening BrikMentor…'=>'Helemaal klaar! BrikMentor wordt geopend…','Open BrikMentor'=>'BrikMentor openen','Automatic setup could not finish. Use your license key to complete it manually.'=>'Het automatisch instellen kon niet worden voltooid. Gebruik je licentiesleutel om het handmatig af te ronden.','Your license key:'=>'Je licentiesleutel:','Finish setup'=>'Instellen afronden','This checkout link expired. Check your email for the license key, or start again.'=>'Deze afrekenlink is verlopen. Zoek de licentiesleutel in je e-mail, of begin opnieuw.','This purchase was already set up. Check your email for the license key.'=>'Deze aankoop is al ingesteld. Zoek de licentiesleutel in je e-mail.','Try again'=>'Opnieuw proberen','Close'=>'Sluiten','Orders'=>'Bestellingen','Products'=>'Producten','Analytics'=>'Analytics','Subscribe to get special offers and updates.'=>'Abonneer je voor speciale aanbiedingen en updates.','Sign up and get %d%% off'=>'Meld je aan en krijg %d%% korting','Get %d%% off'=>'Krijg %d%% korting','Sign up and save'=>'Meld je aan en bespaar','Special offer'=>'Speciale aanbieding','Subscribe'=>'Abonneren','Enter your email'=>'Vul je e-mailadres in','Thanks for subscribing!'=>'Bedankt voor je aanmelding!','Active'=>'Actief','Abandoned'=>'Verlaten','Recovered'=>'Hersteld','Checkout'=>'Afrekenen','Popup'=>'Pop-up','Account'=>'Account','Imported'=>'Geïmporteerd','Please enter a valid email address.'=>'Voer een geldig e-mailadres in.','Email address'=>'E-mailadres','Your discount code'=>'Je kortingscode','Apply it at checkout. Valid for 30 days.'=>'Gebruik hem bij het afrekenen. 30 dagen geldig.','We sent your discount code to %s'=>'We hebben je kortingscode naar %s gestuurd','Check your inbox — if it landed in the Promotions tab, drag it to Primary so you never miss it.'=>'Kijk in je postvak in. Als het bericht in het tabblad Reclame is beland, sleep het dan naar Primair zodat je het niet mist.','Copy'=>'Kopiëren','Copied!'=>'Gekopieerd!','OFF'=>'KORTING','Scratch me'=>'Kras mij','Signup popup coupon (BrikPanel cart abandonment)'=>'Kortingsbon van de aanmeldpop-up (BrikPanel verlaten winkelwagen)','Abandoned Carts'=>'Verlaten winkelwagens','Emails collected from checkout and the signup popup, with a live snapshot of each cart.'=>'E-mailadressen die zijn verzameld bij het afrekenen en via de aanmeldpop-up, met een actuele momentopname van elke winkelwagen.','Show an email signup popup to store visitors.'=>'Bezoekers van de winkel een pop-up voor e-mailaanmelding tonen.','Email popup'=>'E-mailpop-up','Discount percentage for the coupon each popup signup receives. 0 disables the coupon.'=>'Kortingspercentage van de bon die elke aanmelding via de pop-up krijgt. 0 schakelt de bon uit.','Coupon'=>'Kortingsbon','Export CSV'=>'CSV exporteren','Export Excel'=>'Excel exporteren','Import leads from a CSV file. Columns: email (required), first name, last name, phone.'=>'Importeer leads uit een CSV-bestand. Kolommen: e-mail (verplicht), voornaam, achternaam, telefoon.','Import CSV'=>'CSV importeren','Email collection is currently turned off, so no new emails are being captured. You can re-enable it in the settings.'=>'Het verzamelen van e-mailadressen staat momenteel uit, dus er worden geen nieuwe adressen vastgelegd. Je kunt het weer inschakelen in de instellingen.','Emails collected'=>'Verzamelde e-mailadressen','Total cart value'=>'Totale waarde van de winkelwagens','Active carts'=>'Actieve winkelwagens','Value in cart'=>'Waarde in winkelwagen','Recoverable value'=>'Herstelbare waarde','Recovered value'=>'Herstelde waarde','Search'=>'Zoeken','Email or name…'=>'E-mail of naam…','Status'=>'Status','All statuses'=>'Alle statussen','Source'=>'Bron','All sources'=>'Alle bronnen','From'=>'Van','To'=>'Tot','Apply'=>'Toepassen','Email'=>'E-mail','Name'=>'Naam','Cart'=>'Winkelwagen','Last activity'=>'Laatste activiteit','Loading…'=>'Laden…','Previous'=>'Vorige','Next'=>'Volgende','Something went wrong.'=>'Er is iets misgegaan.','No emails captured yet.'=>'Nog geen e-mailadressen vastgelegd.','Delete this entry?'=>'Dit item verwijderen?','Delete'=>'Verwijderen','Details'=>'Details','No cart items recorded.'=>'Geen winkelwagenitems vastgelegd.','Order'=>'Bestelling','item'=>'item','items'=>'items','Popup enabled.'=>'Pop-up ingeschakeld.','Popup disabled.'=>'Pop-up uitgeschakeld.','SKU'=>'SKU','Importing…'=>'Bezig met importeren…','%s emails imported.'=>'%s e-mailadressen geïmporteerd.','%s skipped (already in the list).'=>'%s overgeslagen (staat al in de lijst).','%s skipped (invalid email).'=>'%s overgeslagen (ongeldig e-mailadres).','Nothing new to import.'=>'Niets nieuws om te importeren.','File was larger than the 20,000 row limit; the rest was skipped.'=>'Het bestand was groter dan de limiet van 20.000 rijen; de rest is overgeslagen.','Invalid entry.'=>'Ongeldig item.','Link expired. Refresh the page and try again.'=>'Link verlopen. Vernieuw de pagina en probeer het opnieuw.','First name'=>'Voornaam','Last name'=>'Achternaam','Phone'=>'Telefoon','Items'=>'Artikelen','Cart total'=>'Winkelwagentotaal','Currency'=>'Valuta','Cart contents'=>'Inhoud van de winkelwagen','Created (UTC)'=>'Aangemaakt (UTC)','Last activity (UTC)'=>'Laatste activiteit (UTC)','Abandoned at (UTC)'=>'Verlaten op (UTC)','Recovered at (UTC)'=>'Hersteld op (UTC)','Order ID'=>'Bestel-ID','Export engine unavailable.'=>'Exportmodule niet beschikbaar.','Abandoned carts'=>'Verlaten winkelwagens','Could not generate the Excel file.'=>'Het Excel-bestand kon niet worden gemaakt.','No file received. Please choose a CSV file.'=>'Geen bestand ontvangen. Kies een CSV-bestand.','File is too large. The maximum size is 5 MB.'=>'Het bestand is te groot. De maximale grootte is 5 MB.','The file could not be read.'=>'Het bestand kon niet worden gelezen.','No email column found. Add an "Email" header or put emails in the first column.'=>'Geen e-mailkolom gevonden. Voeg een kolomkop "Email" toe of zet de adressen in de eerste kolom.','No valid email addresses found in the file.'=>'Geen geldige e-mailadressen in het bestand gevonden.','Cart abandonment'=>'Verlaten winkelwagen','Collect customer emails from the checkout page and an optional signup popup, so abandoned carts can be followed up. Collected emails are listed on the Abandoned Carts page.'=>'Verzamel e-mailadressen van klanten via de afrekenpagina en een optionele aanmeldpop-up, zodat je verlaten winkelwagens kunt opvolgen. De verzamelde adressen staan op de pagina Verlaten winkelwagens.','Email collection'=>'E-mailadressen verzamelen','Capture emails typed at checkout (and from the popup) together with a cart snapshot'=>'Leg e-mailadressen die bij het afrekenen (en in de pop-up) worden ingevuld vast, samen met een momentopname van de winkelwagen','Mark cart as abandoned after'=>'Winkelwagen als verlaten markeren na','minutes of inactivity'=>'minuten inactiviteit','A cart with a known email and no activity for this long is marked as abandoned.'=>'Een winkelwagen met een bekend e-mailadres die deze tijd geen activiteit heeft, wordt als verlaten gemarkeerd.','Show a signup popup to store visitors (not shown on the checkout page)'=>'Bezoekers van de winkel een aanmeldpop-up tonen (niet op de afrekenpagina)','Visitors who leave their email here are matched with their cart later, even if they never type an email at checkout. After closing, the popup stays available as a small floating tab.'=>'Bezoekers die hier hun e-mailadres achterlaten, worden later aan hun winkelwagen gekoppeld, ook als ze bij het afrekenen nooit een adres invullen. Na het sluiten blijft de pop-up beschikbaar als klein zwevend tabblad.','Popup discount'=>'Pop-upkorting','% off coupon for popup signups'=>'% kortingsbon voor aanmeldingen via de pop-up','Each signup gets a personal single-use percentage coupon restricted to their email, valid for 30 days. Set to 0 to collect emails without a coupon.'=>'Elke aanmelding krijgt een persoonlijke kortingsbon voor eenmalig gebruik, gekoppeld aan het eigen e-mailadres en 30 dagen geldig. Zet op 0 om e-mailadressen zonder kortingsbon te verzamelen.','Offer animation'=>'Animatie van de aanbieding','Visual style of the animated discount badge at the top of the popup. Only shown while a popup discount is set.'=>'Visuele stijl van de geanimeerde kortingsbadge boven in de pop-up. Wordt alleen getoond zolang er een pop-upkorting is ingesteld.','Sealed envelope: the seal pops and the coupon rises'=>'Verzegelde envelop: het zegel springt open en de bon komt omhoog','Pocket card: coupon springs out of a pocket'=>'Zakkaart: de bon springt uit een zakje','Scratch card: a coin scratches the foil away'=>'Kraskaart: een munt krast de folie weg','Slot machine: reels spin and land on the discount'=>'Gokkast: de rollen draaien en stoppen op de korting','Magnetic assembly: pieces fly in and form the coupon'=>'Magnetische montage: onderdelen vliegen aan en vormen de bon','Classic ticket: floating coupon with a shine sweep'=>'Klassiek ticket: zwevende bon met een glansveeg','Popup title'=>'Titel van de pop-up','Popup message'=>'Bericht in de pop-up','Popup button text'=>'Tekst van de pop-upknop','Email placeholder'=>'Tijdelijke tekst voor het e-mailveld','Success message'=>'Bevestigingsbericht','Floating tab text'=>'Tekst van het zwevende tabblad','Shown on the small tab that stays on the left edge after the popup is closed. Leave empty to use the discount-based default.'=>'Wordt getoond op het kleine tabblad dat na het sluiten van de pop-up aan de linkerrand blijft staan. Laat leeg om de standaardtekst op basis van de korting te gebruiken.','Popup delay'=>'Vertraging van de pop-up','seconds after the page loads'=>'seconden nadat de pagina is geladen','Do not show again for'=>'Niet meer tonen gedurende','days after a visitor closes the floating tab'=>'dagen nadat een bezoeker het zwevende tabblad sluit','Closing the popup itself only collapses it into the floating tab; this cooldown applies when the visitor dismisses the tab too.'=>'Het sluiten van de pop-up klapt hem alleen in tot het zwevende tabblad; deze wachttijd geldt wanneer de bezoeker ook het tabblad wegklikt.','Mark abandoned carts'=>'Verlaten winkelwagens markeren','Flips inactive captured carts to abandoned and notifies integrations.'=>'Zet inactieve vastgelegde winkelwagens om naar verlaten en waarschuwt integraties.','Coupons'=>'Kortingsbonnen','Search coupons...'=>'Kortingsbonnen zoeken...','Add coupon'=>'Kortingsbon toevoegen','All'=>'Alle','Published'=>'Gepubliceerd','Draft'=>'Concept','Trash'=>'Prullenbak','Newest first'=>'Nieuwste eerst','Oldest first'=>'Oudste eerst','Code A-Z'=>'Code A-Z','Code Z-A'=>'Code Z-A','selected'=>'geselecteerd','Select all'=>'Alles selecteren','Deselect all'=>'Alles deselecteren','Publish'=>'Publiceren','Set as draft'=>'Instellen als concept','Move to trash'=>'Verplaatsen naar prullenbak','Code'=>'Code','Type'=>'Type','Amount'=>'Bedrag','Description'=>'Beschrijving','Usage / Limit'=>'Gebruik / Limiet','Revenue'=>'Omzet','Expiry date'=>'Vervaldatum','Edit coupon'=>'Kortingsbon bewerken','General'=>'Algemeen','Coupon code'=>'Kortingsbon-code','e.g. SUMMER2024'=>'bijv. ZOMER2024','Generate'=>'Genereren','Optional description for internal use'=>'Optionele beschrijving voor intern gebruik','Discount type'=>'Kortingstype','Percentage discount'=>'Procentuele korting','Fixed cart discount'=>'Vast winkelwagenkortingsbedrag','Fixed product discount'=>'Vast productkortingsbedrag','Free shipping'=>'Gratis verzending','Usage restrictions'=>'Gebruiksbeperkingen','Minimum spend'=>'Minimumbesteding','No minimum'=>'Geen minimum','Maximum spend'=>'Maximumbesteding','No maximum'=>'Geen maximum','Individual use only'=>'Alleen individueel gebruik','Cannot be used with other coupons'=>'Kan niet samen met andere kortingsbonnen worden gebruikt','Exclude sale items'=>'Aanbiedingen uitsluiten','Search products by name or SKU…'=>'Producten zoeken op naam of SKU…','Limit the coupon to these products. Leave empty to allow all products.'=>'Beperk de kortingsbon tot deze producten. Laat leeg om alle producten toe te staan.','Exclude products'=>'Producten uitsluiten','Search products to exclude…'=>'Zoek producten om uit te sluiten…','Coupon will not apply when the cart contains these products.'=>'Kortingsbon geldt niet wanneer de winkelwagen deze producten bevat.','Product categories'=>'Productcategorieën','Search categories…'=>'Categorieën zoeken…','Coupon applies only to products in these categories. Leave empty to allow all categories.'=>'Kortingsbon geldt alleen voor producten in deze categorieën. Laat leeg om alle categorieën toe te staan.','Exclude categories'=>'Categorieën uitsluiten','Search categories to exclude…'=>'Zoek categorieën om uit te sluiten…','Coupon will not apply to products in these categories.'=>'Kortingsbon geldt niet voor producten in deze categorieën.','Allowed emails'=>'Toegestane e-mails','e.g. jane@example.com, *@team.com'=>'bijv. jane@example.com, *@team.com','Comma- or newline-separated. Wildcards like *@example.com are supported.'=>'Gescheiden door komma\'s of nieuwe regels. Jokertekens zoals *@example.com worden ondersteund.','Usage limits'=>'Gebruikslimieten','Usage limit per coupon'=>'Gebruikslimiet per kortingsbon','Unlimited'=>'Onbeperkt','Usage limit per user'=>'Gebruikslimiet per gebruiker','Limit usage to X items'=>'Beperk gebruik tot X artikelen','All matching items'=>'Alle overeenkomende artikelen','Caps the number of matching items the discount applies to per cart. Only used with product or category restrictions.'=>'Beperkt het aantal overeenkomende artikelen waarop de korting per winkelwagen van toepassing is. Alleen gebruikt met product- of categoriebeperkingen.','Usage count'=>'Gebruiksteller','Cancel'=>'Annuleren','Save changes'=>'Wijzigingen opslaan','Coupon code is required.'=>'Kortingsbon-code is verplicht.','A coupon with this code already exists.'=>'Er bestaat al een kortingsbon met deze code.','Coupon updated!'=>'Kortingsbon bijgewerkt!','Coupon created!'=>'Kortingsbon aangemaakt!','Invalid coupon ID.'=>'Ongeldige kortingsbon-ID.','Coupon not found.'=>'Kortingsbon niet gevonden.','Coupon permanently deleted.'=>'Kortingsbon permanent verwijderd.','Coupon moved to trash.'=>'Kortingsbon naar prullenbak verplaatst.','Coupon status changed to %s.'=>'Kortingsbon-status gewijzigd naar %s.','Coupon duplicated!'=>'Kortingsbon gedupliceerd!','(deleted product #%d)'=>'(verwijderd product #%d)','(deleted category #%d)'=>'(verwijderde categorie #%d)','When your store takes orders in more than one currency, BrikPanel converts every order to your store currency before adding it up, so Revenue, Average Order Value and the sales chart are never a meaningless mix of currencies. If you use a multi-currency plugin such as CURCY, the exact rate from the day of each sale is read automatically from the order — you only need the rates below for currencies that arrive without one.'=>'Wanneer uw winkel bestellingen in meer dan één valuta aanneemt, zet BrikPanel elke bestelling om naar uw winkelvaluta voordat het wordt opgeteld, zodat Omzet, Gemiddelde orderwaarde en de verkoopgrafiek nooit een zinloze mix van valuta\'s zijn. Als u een multivaluta-plugin zoals CURCY gebruikt, wordt de exacte koers van de dag van elke verkoop automatisch uit de bestelling gelezen, u heeft de onderstaande koersen alleen nodig voor valuta\'s die zonder koers binnenkomen.','Exchange rates to your store currency'=>'Wisselkoersen naar uw winkelvaluta','Your store currency is %s. Enter how much one unit of each currency below is worth in it.'=>'Uw winkelvaluta is %s. Voer in hoeveel één eenheid van elke onderstaande valuta daarin waard is.','All of your orders are already in %s, so there is nothing to convert here.'=>'Al uw bestellingen zijn al in %s, dus er valt hier niets om te rekenen.','Leave a rate empty to count those orders at their original number (no conversion). Orders that already carry a rate from your multi-currency plugin ignore the values here and always use their own day-of-sale rate.'=>'Laat een koers leeg om die bestellingen mee te tellen op hun oorspronkelijke bedrag (geen omrekening). Bestellingen die al een koers van uw multivaluta-plugin bevatten, negeren de waarden hierboven en gebruiken altijd hun eigen koers van de verkoopdag.','Customer Analytics'=>'Klantanalytics','Invalid request.'=>'Ongeldig verzoek.','User ID'=>'Gebruikers-ID','Order count'=>'Aantal bestellingen','Total spent (LTV)'=>'Totaal besteed (LTV)','Average order value'=>'Gemiddelde bestelwaarde','Recency (days)'=>'Recentheid (dagen)','First order'=>'Eerste bestelling','Last order'=>'Laatste bestelling','Invalid segment.'=>'Ongeldig segment.','Segment'=>'Segment','R'=>'R','F'=>'F','M'=>'M','Cohort month'=>'Cohortmaand','Period offset (months)'=>'Periode-offset (maanden)','Cohort size'=>'Cohortgrootte','Retained customers'=>'Behouden klanten','Retention rate (%)'=>'Retentiepercentage (%)','Action Scheduler is not available.'=>'Action Scheduler is niet beschikbaar.','Customer metrics recomputed.'=>'Klantmetrics opnieuw berekend.','User #%d'=>'Gebruiker #%d','Exclusions saved.'=>'Uitsluitingen opgeslagen.','Last refreshed: %s'=>'Laatst vernieuwd: %s','Not computed yet — running first sync…'=>'Nog niet berekend — eerste synchronisatie wordt uitgevoerd…','Exclude customers'=>'Klanten uitsluiten','Recompute now'=>'Nu opnieuw berekenen','Lifetime Value'=>'Lifetime Value','RFM Segments'=>'RFM-segmenten','Cohort Retention'=>'Cohortretentie','Total customers'=>'Totaal aantal klanten','Average LTV'=>'Gemiddelde LTV','Median:'=>'Mediaan:','Total LTV'=>'Totale LTV','AOV:'=>'AOV:','Top customer'=>'Topklant','highest lifetime spend'=>'hoogste levenslange besteding','LTV distribution'=>'LTV-verdeling','How many customers fall into each lifetime-spend bracket.'=>'Hoeveel klanten binnen elke levensbestedings-bandbreedte vallen.','Top customers by LTV'=>'Topklanten op LTV','Sorted by lifetime spend, descending. Click a row to open the customer profile.'=>'Gesorteerd op levenslange besteding, aflopend. Klik op een rij om het klantprofiel te openen.','Customer'=>'Klant','AOV'=>'AOV','LTV'=>'LTV','Recency'=>'Recentheid','Customer segments'=>'Klantsegmenten','Each customer is scored 1–5 on Recency, Frequency, and Monetary value, then placed into one of the RFM segments below. Click a card to drill into its customers.'=>'Elke klant krijgt een score van 1–5 op Recentheid, Frequentie en Monetaire waarde en wordt vervolgens in een van de RFM-segmenten hieronder geplaatst. Klik op een kaart om in te zoomen op de klanten ervan.','Segment customers'=>'Segmentklanten','Export this segment (CSV)'=>'Dit segment exporteren (CSV)','Clear selection'=>'Selectie wissen','RFM'=>'RFM','Click a segment above to load its customers.'=>'Klik op een segment hierboven om de klanten ervan te laden.','Cohort retention'=>'Cohortretentie','Each row is a monthly cohort of customers acquired that month. Each cell shows the % of that cohort who placed at least one order N months later.'=>'Elke rij is een maandelijks cohort van klanten die in die maand zijn geworven. Elke cel toont het % van dat cohort dat ten minste één bestelling N maanden later heeft geplaatst.','Window:'=>'Venster:','Last 6 months'=>'Laatste 6 maanden','Last 12 months'=>'Laatste 12 maanden','Last 24 months'=>'Laatste 24 maanden','Average retention by month offset'=>'Gemiddelde retentie per maand-offset','Across all cohorts in the selected window — useful for spotting where the typical drop-off happens.'=>'Over alle cohorten in het geselecteerde venster — nuttig om te zien waar de typische uitval plaatsvindt.','Export matrix (CSV)'=>'Matrix exporteren (CSV)','Exclude customers from analytics'=>'Klanten uitsluiten van analyses','Pick the accounts you do not want counted as customers, for example a point-of-sale or staff login that places many orders. Their orders still count toward your shop revenue and order totals, but they are left out of customer averages, segments, and retention so the numbers reflect your real customers.'=>'Kies de accounts die u niet als klant wilt meetellen, bijvoorbeeld een kassa- of personeelslogin die veel bestellingen plaatst. Hun bestellingen tellen nog steeds mee voor uw winkelomzet en ordertotalen, maar ze worden weggelaten uit klantgemiddelden, segmenten en retentie, zodat de cijfers uw echte klanten weergeven.','People'=>'Personen','Search by name or email…'=>'Zoeken op naam of e-mail…','Roles'=>'Rollen','Everyone with a checked role is excluded too.'=>'Iedereen met een aangevinkte rol wordt ook uitgesloten.','Cost of goods'=>'Kostprijs verkopen','Expenses (taxes, ad spend, supplier costs)'=>'Uitgaven (belastingen, advertentie-uitgaven, leverancierskosten)','Returns (refunds)'=>'Retouren (terugbetalingen)','Coupons (discounts given)'=>'Coupons (gegeven kortingen)','Move up'=>'Omhoog verplaatsen','Move down'=>'Omlaag verplaatsen','Reset to default'=>'Standaard herstellen','Clearing cache…'=>'Cache wissen…','Cache could not be cleared.'=>'Cache kon niet worden gewist.','Toggle navigation'=>'Navigatie schakelen','BrikPanel dashboard'=>'BrikPanel-dashboard','Admin'=>'Admin','Live visitors right now'=>'Live bezoekers nu','live'=>'live','Search orders'=>'Bestellingen zoeken','Create'=>'Aanmaken','New product'=>'Nieuw product','New order'=>'Nieuwe bestelling','New coupon'=>'Nieuwe kortingsbon','New post'=>'Nieuw bericht','Order notifications'=>'Bestelmeldingen','Needs attention'=>'Heeft aandacht nodig','Processing orders'=>'Bestellingen in verwerking','Pending payment'=>'Wacht op betaling','On hold'=>'In de wacht','Out of stock'=>'Niet op voorraad','New customers today'=>'Nieuwe klanten vandaag','Hidden notices from other plugins'=>'Verborgen meldingen van andere plugins','Hidden notices'=>'Verborgen meldingen','From other plugins &amp; themes'=>'Van andere plugins &amp; thema\'s','View store'=>'Winkel bekijken','Your profile'=>'Uw profiel','BrikPanel settings'=>'BrikPanel-instellingen','Network Admin'=>'Netwerkbeheer','Log out'=>'Uitloggen','Purge %s'=>'%s opschonen','Clear cache'=>'Cache wissen','Clear all caches'=>'Alle caches wissen','Pick one or more widgets in "Include WordPress dashboard widgets" above and save. Each embedded widget then appears here so you can choose who sees it.'=>'Kies hierboven onder "WordPress-dashboardwidgets opnemen" een of meer widgets en sla op. Elke ingesloten widget verschijnt dan hier, zodat je kunt kiezen wie hem ziet.','Visible to'=>'Zichtbaar voor','Who can see this widget'=>'Wie deze widget kan zien','Everyone'=>'Iedereen','Admins only'=>'Alleen beheerders','Specific roles'=>'Specifieke rollen','Hide from these roles'=>'Verbergen voor deze rollen','Dashboard'=>'Dashboard','Profit (Revenue, Cost of goods, Net profit)'=>'Winst (Omzet, Kostprijs verkopen, Nettowinst)','KPI cards (Sales, Orders, AOV, Visitors, Conversion)'=>'KPI-kaarten (Verkopen, Bestellingen, AOV, Bezoekers, Conversie)','Sales over time + Live visitors'=>'Verkopen in de tijd + Live bezoekers','Conversion funnel + Order rates'=>'Conversiefunnel + Bestelpercentages','Order locations globe + Top countries/cities'=>'Bestellingenlocaties-globe + Top landen/steden','Top products + Recent orders'=>'Topproducten + Recente bestellingen','Most viewed pages + Most added to cart'=>'Meest bekeken pagina\'s + Meest toegevoegd aan winkelwagen','Visitors by device + Customer types + Traffic sources'=>'Bezoekers per apparaat + Klanttypen + Verkeersbronnen','Customer segments (RFM)'=>'Klantsegmenten (RFM)','Low stock + Customer lifetime value'=>'Lage voorraad + Lifetime value klanten','Subscriptions'=>'Abonnementen','WordPress dashboard widgets'=>'WordPress-dashboardwidgets','Marketplace analytics (BrikMarket)'=>'Marketplace-analytics (BrikMarket)','With Marketplace'=>'Met Marketplace','Copy everything'=>'Alles kopiëren','What does “Copy everything” do?'=>'Wat doet “Alles kopiëren”?','Bundles your store’s key data — KPIs, top products, recent orders, customers and settings — into a single Markdown report and copies it to your clipboard. Paste it into ChatGPT, Claude or any AI tool to get instant analysis, insights and recommendations about your store.'=>'Bundelt de belangrijkste gegevens van uw winkel — KPI\'s, topproducten, recente bestellingen, klanten en instellingen — in één Markdown-rapport en kopieert dit naar uw klembord. Plak het in ChatGPT, Claude of een willekeurige AI-tool om direct analyse, inzichten en aanbevelingen over uw winkel te krijgen.','Ad spend settings'=>'Instellingen advertentie-uitgaven','Connect ad accounts'=>'Advertentieaccounts verbinden','Download the selected period as an Excel workbook (opens in Excel / Google Sheets)'=>'Download de geselecteerde periode als een Excel-werkmap (opent in Excel / Google Sheets)','Today'=>'Vandaag','Yesterday'=>'Gisteren','Last 7 Days'=>'Laatste 7 dagen','Last 30 Days'=>'Laatste 30 dagen','Last 90 Days'=>'Laatste 90 dagen','Custom'=>'Aangepast','Select dates'=>'Datums selecteren','Where this data comes from'=>'Waar deze gegevens vandaan komen','BrikPanel started measuring visitors and conversions on %s, the day it was activated. There is no visitor history before that date, so a recent install can read low or empty here. Your sales and orders are not affected. Those use your full WooCommerce history.'=>'BrikPanel begon op %s met het meten van bezoekers en conversies, de dag waarop het werd geactiveerd. Er is geen bezoekersgeschiedenis vóór die datum, dus een recente installatie kan hier laag of leeg uitkomen. Uw verkopen en bestellingen worden niet beïnvloed. Die gebruiken uw volledige WooCommerce-geschiedenis.','BrikPanel measures visitors and conversions from the day it was activated. There is no visitor history before that, so a recent install can read low or empty here. Your sales and orders are not affected. Those use your full WooCommerce history.'=>'BrikPanel meet bezoekers en conversies vanaf de dag waarop het werd geactiveerd. Er is daarvóór geen bezoekersgeschiedenis, dus een recente installatie kan hier laag of leeg uitkomen. Uw verkopen en bestellingen worden niet beïnvloed. Die gebruiken uw volledige WooCommerce-geschiedenis.','About these numbers'=>'Over deze cijfers','Sales, orders, profit and customer figures use your full WooCommerce order history.'=>'Cijfers voor verkopen, bestellingen, winst en klanten gebruiken uw volledige WooCommerce-orderhistorie.','Visitors, conversion rate and the funnel are measured by BrikPanel from %s, the day it was activated, so they have no earlier history.'=>'Bezoekers, conversiepercentage en de funnel worden door BrikPanel gemeten vanaf %s, de dag waarop het werd geactiveerd, dus ze hebben geen eerdere geschiedenis.','Visitors, conversion rate and the funnel are measured by BrikPanel from the day it was activated, so they have no earlier history.'=>'Bezoekers, conversiepercentage en de funnel worden door BrikPanel gemeten vanaf de dag waarop het werd geactiveerd, dus ze hebben geen eerdere geschiedenis.','Orders placed by store administrators are left out of every figure, so your own test orders do not change the totals.'=>'Bestellingen die door winkelbeheerders zijn geplaatst, worden uit elk cijfer weggelaten, zodat uw eigen testbestellingen de totalen niet wijzigen.','Why this can look low'=>'Waarom dit laag kan lijken','Orders placed by store administrators are not counted here, so test orders you place on your own admin account do not change this figure. Real customer orders are always included.'=>'Bestellingen die door winkelbeheerders zijn geplaatst, worden hier niet meegeteld, dus testbestellingen die u op uw eigen beheerdersaccount plaatst, wijzigen dit cijfer niet. Echte klantbestellingen worden altijd meegeteld.','Total Sales'=>'Totale verkoop','Avg. Order Value'=>'Gem. bestelwaarde','Visitors'=>'Bezoekers','Conversion Rate'=>'Conversiepercentage','The total of all paid orders for the selected dates (Processing and Completed by default), with tax and shipping included and any customer refunds in the period subtracted. Orders placed by store administrators are left out so your own test orders do not change it. You can change which statuses count under Settings, then Analytics.'=>'Het totaal van alle betaalde bestellingen voor de geselecteerde datums (standaard In behandeling en Voltooid), inclusief belasting en verzending en met aftrek van eventuele klantterugbetalingen in de periode. Bestellingen die door winkelbeheerders zijn geplaatst, worden weggelaten zodat uw eigen testbestellingen het niet wijzigen. U kunt onder Instellingen, dan Analyses wijzigen welke statussen meetellen.','The total of all paid orders for the selected dates (Processing and Completed by default), with tax and shipping included. Orders placed by store administrators are left out so your own test orders do not change it. You can change which statuses count under Settings, then Analytics.'=>'Het totaal van alle betaalde bestellingen voor de geselecteerde datums (standaard In behandeling en Voltooid), inclusief belasting en verzending. Bestellingen die door winkelbeheerders zijn geplaatst, worden weggelaten zodat uw eigen testbestellingen het niet wijzigen. U kunt onder Instellingen, dan Analyses wijzigen welke statussen meetellen.','How Revenue is calculated'=>'Hoe Omzet wordt berekend','Show revenue breakdown'=>'Omzetuitsplitsing tonen','Cost of Goods'=>'Kostprijs verkopen','How Cost of Goods is calculated'=>'Hoe Kostprijs van verkochte goederen wordt berekend','The "Cost of goods" you set on each product, multiplied by the quantity sold in paid orders for the period. Variations use their own cost and fall back to the parent product. Any product with no cost set counts as zero, which overstates Net profit, so fill those in for an accurate margin.'=>'De „kostprijs van goederen” die u per product instelt, vermenigvuldigd met het aantal verkocht in betaalde bestellingen in de periode. Variaties gebruiken hun eigen kostprijs en vallen terug op het bovenliggende product. Elk product zonder ingestelde kostprijs telt als nul, wat de nettowinst overschat, dus vul die in voor een nauwkeurige marge.','Expenses'=>'Uitgaven','What Expenses includes'=>'Wat Uitgaven omvat','Operating costs for the period: order tax, ad spend from connected ad platforms (store currency only), supplier and stock costs from received purchase orders, plus anything logged in the Expenses module. Open the breakdown to see each part.'=>'Bedrijfskosten voor de periode: orderbelasting, advertentie-uitgaven van gekoppelde advertentieplatforms (alleen winkelvaluta), leveranciers- en voorraadkosten van ontvangen inkooporders, plus alles wat in de module Uitgaven is geregistreerd. Open de uitsplitsing om elk onderdeel te zien.','Add expense'=>'Uitgave toevoegen','Show expense breakdown'=>'Uitgavenoverzicht tonen','Net Profit'=>'Nettowinst','How Net Profit is calculated'=>'Hoe Nettowinst wordt berekend','Revenue minus Cost of goods minus Expenses. This is what is left after the cost of what you sold and your operating costs for the period. A negative figure means a loss.'=>'Omzet min kostprijs van goederen min uitgaven. Dit is wat overblijft na de kostprijs van wat u verkocht en uw bedrijfskosten voor de periode. Een negatief cijfer betekent verlies.','Fixed amount'=>'Vast bedrag','Percentage of revenue'=>'Percentage van de omzet','Title'=>'Titel','e.g. Rent, Salaries, Credit card commission'=>'bijv. Huur, Salarissen, Creditcardcommissie','Date'=>'Datum','Repeats'=>'Herhaalt','One-time'=>'Eenmalig','Monthly'=>'Maandelijks','Weekly'=>'Wekelijks','Yearly'=>'Jaarlijks','Note (optional)'=>'Notitie (optioneel)','What is this for?'=>'Waar dient dit voor?','A repeating expense is counted automatically in every period from this date onward.'=>'Een terugkerende uitgave wordt vanaf deze datum automatisch in elke periode meegeteld.','A percentage cost is applied to your revenue in every period from this date onward (great for card or marketplace commission).'=>'Een percentagekost wordt vanaf deze datum in elke periode op uw omzet toegepast (ideaal voor kaart- of marktplaatscommissie).','Save expense'=>'Uitgave opslaan','Marketplace Sales'=>'Marketplace-verkopen','Marketplace Orders'=>'Marketplace-bestellingen','Avg. Marketplace Order'=>'Gem. Marketplace-bestelling','Share of Total Revenue'=>'Aandeel van totale omzet','Revenue by Marketplace'=>'Omzet per Marketplace','Loading...'=>'Laden...','Marketplace Share'=>'Marketplace-aandeel','Top Categories from Marketplaces'=>'Topcategorieën uit Marketplaces','Top Marketplace Products'=>'Top Marketplace-producten','Sales Over Time'=>'Verkopen in de tijd','Live Visitors'=>'Live bezoekers','No active visitors'=>'Geen actieve bezoekers','Conversion Funnel'=>'Conversiefunnel','Order Rates'=>'Bestelpercentages','Order Locations'=>'Bestellingenlocaties','View mode'=>'Weergavemodus','Customers'=>'Klanten','Toggle theme'=>'Thema schakelen','Top Countries'=>'Top landen','Top Cities'=>'Top steden','Top Products'=>'Topproducten','Recent Orders'=>'Recente bestellingen','Most Viewed Pages'=>'Meest bekeken pagina\'s','Most Added to Cart'=>'Meest toegevoegd aan winkelwagen','Visitors by Device'=>'Bezoekers per apparaat','Device breakdown view'=>'Apparaatoverzichtweergave','Sources'=>'Bronnen','Top Referrers'=>'Belangrijkste verwijzers','Customer Types'=>'Klanttypes','Customer Segments (RFM)'=>'Klantsegmenten (RFM)','View details →'=>'Details bekijken →','%s product'=>'%s product' . "\0" . '%s producten','%s variation'=>'%s variatie' . "\0" . '%s variaties','%s sellable item'=>'%s verkoopbaar item' . "\0" . '%s verkoopbare items','%s unit in stock'=>'%s eenheid op voorraad' . "\0" . '%s eenheden op voorraad','Low Stock'=>'Lage voorraad','Sellable items counts each variable product by its purchasable variations, not as a single product. Units in stock is the total on-hand quantity across all stock-managed products.'=>'Verkoopbare items tellen elk variabel product op basis van de koopbare variaties, niet als één product. Eenheden op voorraad is de totale aanwezige hoeveelheid over alle producten met voorraadbeheer.','Customer Lifetime Value'=>'Customer Lifetime Value','WordPress widgets'=>'WordPress-widgets','Widget failed to load.'=>'Widget kon niet worden geladen.','Cancelled'=>'Geannuleerd','Expired'=>'Verlopen','Pending cancellation'=>'Annulering in afwachting','Tax'=>'Belasting','Other'=>'Overig','Supplier / stock'=>'Leverancier / voorraad','Gross sales'=>'Brutoverkopen','Returns'=>'Retouren','Coupons (already in totals)'=>'Coupons (al in totalen)','Custom range'=>'Aangepast bereik','%d day'=>'%d dag' . "\0" . '%d dagen','Guest'=>'Gast','Organic'=>'Organisch','Referral'=>'Verwijzing','Campaign'=>'Campagne','Direct'=>'Direct','You do not have permission to export dashboard data.'=>'U heeft geen toestemming om dashboardgegevens te exporteren.','Export engine unavailable on this server.'=>'Exporteermotor niet beschikbaar op deze server.','New'=>'Nieuw','BrikPanel Report'=>'BrikPanel-rapport','Website'=>'Website','Report period'=>'Rapportperiode','Duration'=>'Duur','Generated'=>'Gegenereerd','Key Metrics'=>'Belangrijkste metrics','Metric'=>'Metric','Value'=>'Waarde','Change vs previous period'=>'Wijziging t.o.v. vorige periode','Conversion Rate (%)'=>'Conversiepercentage (%)','Profit'=>'Winst','Amount (%s)'=>'Bedrag (%s)','Context'=>'Context','Same as Total Sales'=>'Hetzelfde als Totale verkoop','%s%% of revenue'=>'%s%% van de omzet','%s%% margin'=>'%s%% marge','Returns & Refunds'=>'Retouren & Terugbetalingen','Returned / refunded orders'=>'Geretourneerde / terugbetaalde bestellingen','Total orders'=>'Totaal aantal bestellingen','Return & refund rate (%)'=>'Retour- & terugbetalingspercentage (%)','Customer Lifetime Value (all-time)'=>'Customer Lifetime Value (gehele periode)','Top customer LTV'=>'Top klant-LTV','Repeat customers'=>'Terugkerende klanten','Repeat rate (%)'=>'Herhalingspercentage (%)','Note: the Orders tab lists every order placed in this period (all statuses). The “Orders” metric above counts paid orders only (processing + completed).'=>'Opmerking: het tabblad Bestellingen vermeldt elke bestelling die in deze periode is geplaatst (alle statussen). De metric “Bestellingen” hierboven telt alleen betaalde bestellingen (in verwerking + voltooid).','Stage'=>'Fase','Count'=>'Aantal','% of visitors'=>'% van de bezoekers','Product views'=>'Productweergaven','Add to cart'=>'Toevoegen aan winkelwagen','Share (%)'=>'Aandeel (%)','Successful'=>'Succesvol','Failed'=>'Mislukt','Device'=>'Apparaat','Desktop'=>'Desktop','Mobile'=>'Mobiel','Tablet'=>'Tablet','Total'=>'Totaal','New vs Repeat (this period)'=>'Nieuw vs Herhaling (deze periode)','New customers'=>'Nieuwe klanten','RFM Segments (all-time)'=>'RFM-segmenten (gehele periode)','Customer metrics will appear after the nightly recompute.'=>'Klantmetrics verschijnen na de nachtelijke herberekening.','Product'=>'Product','Qty Sold'=>'Aantal verkocht','No data for this period'=>'Geen gegevens voor deze periode','Views'=>'Weergaven','Cart Adds'=>'Toevoegingen winkelwagen','Revenue (%s)'=>'Omzet (%s)','Country'=>'Land','City'=>'Stad','Remaining'=>'Resterend','All products are sufficiently stocked'=>'Alle producten hebben voldoende voorraad','Order #'=>'Bestelling #','Total (%s)'=>'Totaal (%s)','No orders in this period'=>'Geen bestellingen in deze periode','Summary'=>'Samenvatting','Funnel'=>'Funnel','Order Status'=>'Bestelstatus','Devices'=>'Apparaten','Customer Segments'=>'Klantsegmenten','Most Viewed'=>'Meest bekeken','Countries'=>'Landen','Cities'=>'Steden','Orders (%d)'=>'Bestellingen (%d)','Could not generate the Excel file. Please try again.'=>'Kon het Excel-bestand niet genereren. Probeer het opnieuw.','Logo &amp; store name'=>'Logo &amp; winkelnaam','Live visitors counter'=>'Teller voor live bezoekers','Search bar'=>'Zoekbalk','Quick create button'=>'Knop Snel aanmaken','Hidden notices bell'=>'Bel voor verborgen meldingen','View store button'=>'Knop Winkel bekijken','Custom shortcut button'=>'Aangepaste snelkoppelingsknop','User menu'=>'Gebruikersmenu','Who can see this control'=>'Wie dit element kan zien','Items in the create menu'=>'Items in het aanmaakmenu','Set a label and a target, then turn the button on above. The button stays hidden until both are filled in.'=>'Stel een label en een bestemming in en zet de knop hierboven aan. De knop blijft verborgen totdat beide zijn ingevuld.','Button label'=>'Label van de knop','All orders'=>'Alle bestellingen','Button link'=>'Link van de knop','Operational Expenses'=>'Operationele uitgaven','Track your operational costs to calculate net profit accurately.'=>'Houd uw operationele kosten bij om de nettowinst nauwkeurig te berekenen.','Total (filtered)'=>'Totaal (gefilterd)','Entries'=>'Vermeldingen','All titles'=>'Alle titels','Recurring'=>'Terugkerend','Optional notes…'=>'Optionele notities…','Delete this expense?'=>'Deze uitgave verwijderen?','No expenses found.'=>'Geen uitgaven gevonden.','Edit expense'=>'Uitgave bewerken','Ongoing'=>'Doorlopend','Edit'=>'Bewerken','Required fields missing.'=>'Verplichte velden ontbreken.','Amount must be a positive number.'=>'Bedrag moet een positief getal zijn.','A percentage must be between 0 and 100.'=>'Een percentage moet tussen 0 en 100 liggen.','Database error.'=>'Databasefout.','Invalid ID.'=>'Ongeldige ID.','Google Sheets integration'=>'Google Sheets-integratie','Sync your orders, customers, and analytics straight to Google Sheets. The integration is currently in beta — turn it off below to hide the admin page and stop all background sync jobs. Your connection and per-flow settings stay saved, so turning it back on restores everything.'=>'Synchroniseer uw bestellingen, klanten en analytics rechtstreeks naar Google Sheets. De integratie is momenteel in bèta — schakel deze hieronder uit om de adminpagina te verbergen en alle achtergrondsynchronisaties te stoppen. Uw verbinding en instellingen per flow blijven bewaard, dus opnieuw inschakelen herstelt alles.','Enable Google Sheets integration'=>'Google Sheets-integratie inschakelen','When on, the Google Sheets admin menu, sync flows and AJAX endpoints are active. When off, the entire module is dormant: no menu item, no scheduled jobs, no order-write listeners.'=>'Indien aan zijn het Google Sheets-adminmenu, de synchronisatieflows en AJAX-endpoints actief. Indien uit is de hele module slapend: geen menu-item, geen geplande taken, geen bestel-write-listeners.','Not connected to Google Sheets.'=>'Niet verbonden met Google Sheets.','Request to Google Sheets failed after retries.'=>'Verzoek aan Google Sheets mislukte na meerdere pogingen.','Sheets — customers + RFM snapshot'=>'Sheets — klanten + RFM-snapshot','Order number'=>'Bestelnummer','Order date'=>'Besteldatum','Order status'=>'Bestelstatus','Subtotal'=>'Subtotaal','Tax total'=>'Belastingtotaal','Shipping total'=>'Verzendingstotaal','Discount total'=>'Kortingstotaal','Order total'=>'Besteltotaal','Payment method (key)'=>'Betaalmethode (sleutel)','Payment method'=>'Betaalmethode','Transaction ID'=>'Transactie-ID','Coupon codes'=>'Kortingsbon-codes','Customer note'=>'Klantnotitie','Customer user ID'=>'Klantgebruikers-ID','Shipping method'=>'Verzendmethode','Order COGS total'=>'COGS-totaal van bestelling','Billing first name'=>'Factuur-voornaam','Billing last name'=>'Factuur-achternaam','Billing email'=>'Factuur-e-mail','Billing phone'=>'Factuur-telefoon','Billing address 1'=>'Factuuradres 1','Billing address 2'=>'Factuuradres 2','Billing city'=>'Factuurstad','Billing state'=>'Factuurprovincie','Billing postcode'=>'Factuurpostcode','Billing country'=>'Factuurland','Shipping first name'=>'Verzendvoornaam','Shipping last name'=>'Verzendachternaam','Shipping address 1'=>'Verzendadres 1','Shipping address 2'=>'Verzendadres 2','Shipping city'=>'Verzendstad','Shipping state'=>'Verzendprovincie','Shipping postcode'=>'Verzendpostcode','Shipping country'=>'Verzendland','Line item ID'=>'Regelitem-ID','Product ID'=>'Product-ID','Variation ID'=>'Variatie-ID','Product name'=>'Productnaam','Variation attributes'=>'Variatie-attributen','Quantity'=>'Aantal','Unit price'=>'Eenheidsprijs','Line subtotal'=>'Regelsubtotaal','Line tax'=>'Regelbelasting','Line total'=>'Regeltotaal','Line COGS (cost × qty)'=>'Regel-COGS (kostprijs × aantal)','Parent ID'=>'Bovenliggende ID','Short description'=>'Korte beschrijving','Price'=>'Prijs','Regular price'=>'Reguliere prijs','Sale price'=>'Aanbiedingsprijs','Cost (COGS)'=>'Kostprijs (COGS)','Stock'=>'Voorraad','Stock status'=>'Voorraadstatus','Permalink'=>'Permalink','Customer key'=>'Klantsleutel','First order date'=>'Eerste besteldatum','Last order date'=>'Laatste besteldatum','Total spent'=>'Totaal besteed','Recency score (R)'=>'Recentheidsscore (R)','Frequency score (F)'=>'Frequentiescore (F)','Monetary score (M)'=>'Monetaire score (M)','RFM segment'=>'RFM-segment','Custom field'=>'Aangepast veld','Almost there: Google did not grant access to your spreadsheets. On the Google permission screen, please keep the "See, edit, create and delete only the specific Google Drive files you use with this app" box checked, then connect again.'=>'Bijna klaar: Google heeft geen toegang verleend tot uw spreadsheets. Houd op het Google-toestemmingsscherm het selectievakje "Alleen de specifieke Google Drive-bestanden zien, bewerken, maken en verwijderen die u met deze app gebruikt" aangevinkt en maak opnieuw verbinding.','Google Sheets connected.'=>'Google Sheets verbonden.','Sheets — flush new orders to Google Sheets'=>'Sheets — nieuwe bestellingen doorsturen naar Google Sheets','Sheets — scheduled bulk order export'=>'Sheets — geplande bulkbestellingenexport','Sheets — update changed-status order rows'=>'Sheets — bijwerken van bestelrijen met gewijzigde status','Sheets — pull order status changes from Google Sheets'=>'Sheets — bestelstatuswijzigingen ophalen uit Google Sheets','Status changed via Google Sheets sync.'=>'Status gewijzigd via Google Sheets-synchronisatie.','Sheets — push product changes to Google Sheets'=>'Sheets — productwijzigingen naar Google Sheets sturen','Sheets — pull product changes from Google Sheets'=>'Sheets: productwijzigingen ophalen uit Google Sheets','Sheets — reports snapshot'=>'Sheets — rapportensnapshot','Window'=>'Venster','Successful orders'=>'Succesvolle bestellingen','Conversion rate %'=>'Conversiepercentage %','COGS %'=>'COGS %','Ad spend'=>'Advertentie-uitgaven','Other expenses'=>'Overige uitgaven','Total expenses'=>'Totale uitgaven','Expenses %'=>'Uitgaven %','Net profit'=>'Nettowinst','Net margin %'=>'Nettomarge %','Conversion %'=>'Conversie %','Units sold'=>'Verkochte eenheden','Checkout started'=>'Afrekenen gestart','Google Sheets'=>'Google Sheets','Connecting to Google…'=>'Verbinden met Google…','Disconnect from Google Sheets?'=>'Verbinding met Google Sheets verbreken?','Sync queued. Check back in a moment.'=>'Synchronisatie in wachtrij. Kom zo meteen terug.','Spreadsheet created.'=>'Spreadsheet aangemaakt.','Creating spreadsheet…'=>'Spreadsheet aanmaken…','Validating…'=>'Valideren…','Spreadsheet is reachable.'=>'Spreadsheet is bereikbaar.','Opening Google Picker…'=>'Google Picker openen…','Could not open the Google Picker. Please try again.'=>'Kon de Google Picker niet openen. Probeer het opnieuw.','Picking an existing spreadsheet is not available yet. Create a new one below.'=>'Het kiezen van een bestaande spreadsheet is nog niet beschikbaar. Maak hieronder een nieuwe.','BrikPanel does not have access yet. Open the spreadsheet, share it with %s, then click Validate.'=>'BrikPanel heeft nog geen toegang. Open de spreadsheet, deel deze met %s en klik vervolgens op Valideren.','This will WIPE the current target tab in Google Sheets and then re-push every order from scratch. Any rows you added manually to that tab will be lost. Continue?'=>'Dit WIST het huidige doeltabblad in Google Sheets en pusht vervolgens elke bestelling opnieuw vanaf nul. Rijen die u handmatig aan dat tabblad heeft toegevoegd, gaan verloren. Doorgaan?','Resetting…'=>'Resetten…','in %d min (auto-refreshed)'=>'over %d min (automatisch vernieuwd)','Pulling changes from Sheets…'=>'Wijzigingen ophalen uit Sheets…','This will WIPE the current Products tab in Google Sheets and then re-push every product from scratch. Any rows you added manually to that tab will be lost. Continue?'=>'Hiermee wordt het huidige tabblad Producten in Google Sheets GEWIST en wordt elk product opnieuw verzonden. Handmatig toegevoegde rijen gaan verloren. Doorgaan?','Connect Google Sheets first.'=>'Verbind eerst Google Sheets.','Google Drive access was not granted for this connection. Please disconnect and reconnect, keeping the Google Drive permission checked on the consent screen.'=>'Google Drive-toegang is niet verleend voor deze verbinding. Verbreek de verbinding en maak opnieuw verbinding, waarbij u de Google Drive-toestemming aangevinkt houdt op het toestemmingsscherm.','Picking an existing spreadsheet is not available yet. Create a new BrikPanel spreadsheet instead.'=>'Het kiezen van een bestaande spreadsheet is nog niet beschikbaar. Maak in plaats daarvan een nieuwe BrikPanel-spreadsheet aan.','Google session expired. Re-authorize and try again.'=>'Google-sessie verlopen. Autoriseer opnieuw en probeer het opnieuw.','Could not parse a spreadsheet ID from that input.'=>'Kon geen spreadsheet-ID parsen uit die invoer.','BrikPanel can only use spreadsheets you create here or hand over with the “Choose existing spreadsheet” picker. Use the picker to grant access to this file.'=>'BrikPanel kan alleen spreadsheets gebruiken die u hier aanmaakt of overdraagt met de “Bestaande spreadsheet kiezen”-picker. Gebruik de picker om toegang tot dit bestand te verlenen.','Spreadsheet not found. Check the URL.'=>'Spreadsheet niet gevonden. Controleer de URL.','Spreadsheet created but no ID returned.'=>'Spreadsheet aangemaakt maar geen ID geretourneerd.','Invalid "include orders from" date. Use the date picker.'=>'Ongeldige datum voor "bestellingen meenemen vanaf". Gebruik de datumkiezer.','Unknown settings group.'=>'Onbekende instellingengroep.','Unknown flow.'=>'Onbekende flow.','Pick or create a target spreadsheet first.'=>'Kies eerst een doelspreadsheet of maak er een aan.','Enable this sync first, then click Save before clicking Sync now.'=>'Schakel eerst deze synchronisatie in, klik vervolgens op Opslaan voordat u op Nu synchroniseren klikt.','No orders matched the selected status filters and "include orders from" date. Adjust those settings and try again.'=>'Geen bestellingen kwamen overeen met de geselecteerde statusfilters en de datum "bestellingen meenemen vanaf". Pas die instellingen aan en probeer het opnieuw.','No new orders to sync — every matching order is already marked synced. To wipe the target tab and re-push the full history, click "Reset & re-push everything".'=>'Geen nieuwe bestellingen om te synchroniseren — elke overeenkomende bestelling is al gemarkeerd als gesynchroniseerd. Om het doeltabblad te wissen en de volledige geschiedenis opnieuw te pushen, klikt u op "Resetten & alles opnieuw pushen".','Synced %2$d order (%1$d rows).'=>'%2$d bestelling gesynchroniseerd (%1$d rijen).' . "\0" . '%2$d bestellingen gesynchroniseerd (%1$d rijen).','More running in background…'=>'Meer wordt op de achtergrond uitgevoerd…','Pushed %1$d new and updated %2$d existing product rows.'=>'%1$d nieuwe productrijen verzonden en %2$d bestaande bijgewerkt.','Refreshed %2$d report tabs (%1$d rows).'=>'%2$d rapporttabbladen vernieuwd (%1$d rijen).','%1$s ago, %2$d rows'=>'%1$s geleden, %2$d rijen','Enable two-way sync for orders first, then click Save before clicking Pull now.'=>'Schakel eerst de tweerichtingssynchronisatie voor bestellingen in, klik op Opslaan en daarna op „Nu ophalen".','Checked %1$d order rows. Applied %2$d status changes from Sheets, %3$d conflicts skipped.'=>'%1$d bestelregels gecontroleerd. %2$d statuswijzigingen uit Sheets toegepast, %3$d conflicten overgeslagen.','Enable two-way sync for products first, then click Save before clicking Pull now.'=>'Schakel eerst de tweerichtingssynchronisatie voor producten in, klik op Opslaan en daarna op „Nu ophalen".','Checked %1$d product rows. Applied %2$d changes from Sheets, %3$d conflicts skipped.'=>'%1$d productrijen gecontroleerd. %2$d wijzigingen uit Sheets toegepast, %3$d conflicten overgeslagen.','Sync state cleared and target tab wiped. Click "Sync now" to repopulate it.'=>'Synchronisatiestatus gewist en doeltabblad geleegd. Klik op "Nu synchroniseren" om het opnieuw te vullen.','Sync state cleared, but the target tab could not be wiped (check connection). Click "Sync now" anyway.'=>'Synchronisatiestatus gewist, maar het doeltabblad kon niet worden geleegd (controleer de verbinding). Klik toch op "Nu synchroniseren".','Two-way columns'=>'Tweerichtingskolommen','Edits you make in the sheet are written back to your store for these columns only: %s.'=>'Wijzigingen die u in het blad maakt, worden alleen voor deze kolommen teruggeschreven naar uw winkel: %s.','Every other column is one-way (store to sheet). Anything you type into those cells is display-only and will be overwritten on the next sync. Columns that sync back are marked with this glyph in the sheet header.'=>'Elke andere kolom is eenrichting (winkel naar blad). Alles wat u in die cellen typt, is alleen-weergave en wordt bij de volgende synchronisatie overschreven. Kolommen die terugsynchroniseren zijn gemarkeerd met dit teken in de bladkop.','Edits to this column sync back to your store'=>'Wijzigingen in deze kolom synchroniseren terug naar uw winkel','two-way'=>'tweerichting','Show more columns'=>'Meer kolommen tonen','Custom checkout / order fields'=>'Aangepaste afreken- / ordervelden','Save columns'=>'Kolommen opslaan','Recent activity'=>'Recente activiteit','View error log'=>'Foutenlogboek bekijken','Send your orders, customers, and analytics straight to a Google Sheet.'=>'Stuur uw bestellingen, klanten en analytics rechtstreeks naar een Google Sheet.','Connection'=>'Verbinding','Reports'=>'Rapporten','Connect your Google account'=>'Verbind uw Google-account','BrikPanel uses a single, narrow Google permission — no app verification screen, no scary “unverified app” warning. It can only touch a spreadsheet it creates for you or one you explicitly hand over. The rest of your Google Drive stays invisible to BrikPanel.'=>'BrikPanel gebruikt één enkele, beperkte Google-toestemming — geen app-verificatiescherm, geen enge “niet-geverifieerde app”-waarschuwing. Het kan alleen een spreadsheet aanraken die het voor u aanmaakt of een die u expliciet overdraagt. De rest van uw Google Drive blijft onzichtbaar voor BrikPanel.','Drive (per-file) — create a new spreadsheet, or open only the one you pick'=>'Drive (per bestand) — maak een nieuwe spreadsheet of open alleen degene die u kiest','Email — to display which Google account is connected'=>'E-mail — om weer te geven welk Google-account is verbonden','Connect Google Sheets'=>'Verbinden met Google Sheets','Google Drive access is missing.'=>'Google Drive-toegang ontbreekt.','Your account is connected, but the Google Drive permission was not granted, so creating or choosing a spreadsheet will fail. Click Disconnect, then connect again and keep the Google Drive checkbox ticked on the permission screen.'=>'Uw account is verbonden, maar de Google Drive-toestemming is niet verleend, dus het aanmaken of kiezen van een spreadsheet zal mislukken. Klik op Verbinding verbreken, maak vervolgens opnieuw verbinding en houd het Google Drive-selectievakje aangevinkt op het toestemmingsscherm.','Token expires'=>'Token verloopt','in %d minute (auto-refreshed)'=>'over %d minuut (automatisch vernieuwd)' . "\0" . 'over %d minuten (automatisch vernieuwd)','unknown'=>'onbekend','Target spreadsheet'=>'Doelspreadsheet','One spreadsheet is used for every flow. Each flow writes to its own tab inside it.'=>'Eén spreadsheet wordt gebruikt voor elke flow. Elke flow schrijft naar zijn eigen tabblad daarbinnen.','Open in Google Sheets ↗'=>'Openen in Google Sheets ↗','Use an existing spreadsheet'=>'Gebruik een bestaande spreadsheet','Pick one of your Google spreadsheets. You only ever grant BrikPanel access to the single file you choose.'=>'Kies een van uw Google-spreadsheets. U verleent BrikPanel altijd alleen toegang tot het enkele bestand dat u kiest.','Choose existing spreadsheet'=>'Bestaande spreadsheet kiezen','or'=>'of','Create a new spreadsheet for BrikPanel'=>'Maak een nieuwe spreadsheet aan voor BrikPanel','BrikPanel — %s'=>'BrikPanel — %s','Order sync'=>'Bestellingen-synchronisatie','Push WooCommerce orders to a tab. Each row is one line item — variations get their own row with attribute columns.'=>'Push WooCommerce-bestellingen naar een tabblad. Elke rij is één regelitem — variaties krijgen een eigen rij met attribuutkolommen.','Enable order sync'=>'Bestellingen-synchronisatie inschakelen','Target tab name'=>'Naam doeltabblad','Real-time append on new order'=>'Real-time toevoegen bij nieuwe bestelling','Bulk export schedule'=>'Bulkexportschema','Manual only'=>'Alleen handmatig','Hourly'=>'Per uur','Every 4 hours'=>'Elke 4 uur','Daily'=>'Dagelijks','Bulk export — include orders from'=>'Bulkexport — bestellingen meenemen vanaf','Statuses to export'=>'Te exporteren statussen','Shipping methods to export'=>'Te exporteren verzendmethoden','Leave every box unchecked to export orders regardless of shipping method. Pick one or more to export only orders that used those methods.'=>'Laat elk vakje uitgevinkt om bestellingen te exporteren ongeacht de verzendmethode. Kies er een of meer om alleen bestellingen te exporteren die die methoden gebruikten.','Two-way sync: apply status changes from Sheets'=>'Tweerichtingssynchronisatie: statuswijzigingen uit Sheets toepassen','When on, BrikPanel polls the Orders tab and writes any order_status edits back to WooCommerce. Only the Order status column is read back; other edits are display-only and get overwritten on the next push.'=>'Wanneer ingeschakeld, peilt BrikPanel het tabblad Bestellingen en schrijft eventuele order_status-bewerkingen terug naar WooCommerce. Alleen de kolom Bestelstatus wordt teruggelezen; andere bewerkingen zijn alleen ter weergave en worden bij de volgende push overschreven.','Poll interval'=>'Pollingsinterval','Every 2 minutes'=>'Elke 2 minuten','Every 5 minutes'=>'Elke 5 minuten','Every 15 minutes'=>'Elke 15 minuten','Read the Orders tab right now and apply any status changes back to WooCommerce.'=>'Lees nu het tabblad Bestellingen en pas statuswijzigingen toe in WooCommerce.','Pull now'=>'Nu ophalen','Wipe the target tab in Google Sheets and re-push the full order history from scratch. Any manual edits in that tab will be lost.'=>'Maak het doeltabblad in Google Sheets leeg en push de volledige bestelgeschiedenis opnieuw vanaf nul. Handmatige bewerkingen in dat tabblad gaan verloren.','Reset & re-push everything'=>'Resetten & alles opnieuw pushen','Columns to export'=>'Te exporteren kolommen','Mandatory columns (Order ID, Line item ID) are always included so we can de-duplicate rows.'=>'Verplichte kolommen (Bestel-ID, Regelitem-ID) worden altijd meegenomen zodat we rijen kunnen ontdubbelen.','Product sync'=>'Productsynchronisatie','Push WooCommerce products and variations to a tab so you can review stock at a glance. Variations get their own row. Edits to the Stock column flow back to WooCommerce.'=>'Stuur WooCommerce-producten en -variaties naar een tabblad om de voorraad in één oogopslag te bekijken. Variaties krijgen een eigen rij. Bewerkingen in de kolom Voorraad worden teruggestuurd naar WooCommerce.','Enable product sync'=>'Productsynchronisatie inschakelen','Categories to sync'=>'Te synchroniseren categorieën','Leave every box unchecked to sync all products. Pick one or more categories to sync only those products and their variations. Sub-categories are included automatically.'=>'Laat elk vakje uitgevinkt om alle producten te synchroniseren. Kies een of meer categorieën om alleen die producten en hun variaties te synchroniseren. Subcategorieën worden automatisch meegenomen.','No product categories found yet.'=>'Nog geen productcategorieën gevonden.','Changing the categories? After saving, click "Sync now" — the tab is rebuilt from scratch to match the new selection, with no empty gaps.'=>'Categorieën wijzigen? Klik na het opslaan op „Nu synchroniseren”, het tabblad wordt vanaf nul opnieuw opgebouwd om bij de nieuwe selectie te passen, zonder lege gaten.','Two-way sync: apply stock edits from Sheets'=>'Tweerichtingssynchronisatie: voorraadbewerkingen uit Sheets toepassen','When on, BrikPanel polls the Products tab and writes any Stock cell edits back to WooCommerce. Only the Stock column is read back; other edits (price, name, etc.) are display-only and get overwritten on the next push.'=>'Wanneer ingeschakeld, peilt BrikPanel het tabblad Producten en schrijft eventuele Voorraad-celbewerkingen terug naar WooCommerce. Alleen de kolom Voorraad wordt teruggelezen; andere bewerkingen (prijs, naam, enz.) zijn alleen ter weergave en worden bij de volgende push overschreven.','Read the Products tab right now and apply any Stock changes back to WooCommerce.'=>'Lees nu het tabblad Producten en pas voorraadwijzigingen toe in WooCommerce.','Wipe the Products tab in Google Sheets and re-push every product from scratch. Any manual edits in that tab will be lost.'=>'Wis het tabblad Producten in Google Sheets en stuur elk product opnieuw vanaf nul. Handmatige bewerkingen in dat tabblad gaan verloren.','Product ID is mandatory so rows can be de-duplicated. Stock is the only column that flows back to WooCommerce.'=>'Het Product-ID is verplicht zodat rijen kunnen worden ontdubbeld. Voorraad is de enige kolom die terugstroomt naar WooCommerce.','Reports sync'=>'Rapporten-synchronisatie','Push BrikPanel\'s computed analytics into dedicated tabs. Each push overwrites the tab so you always see \'as-of-last-sync\' values.'=>'Push de berekende analytics van BrikPanel naar speciale tabbladen. Elke push overschrijft het tabblad zodat u altijd \'tot laatste synchronisatie\'-waarden ziet.','Enable reports sync'=>'Rapporten-synchronisatie inschakelen','Snapshot interval'=>'Snapshot-interval','Every 6 hours'=>'Elke 6 uur','BrikPanel — Sales Summary'=>'BrikPanel — Verkoopsamenvatting','multi-window revenue, orders, AOV, conversion.'=>'omzet, bestellingen, AOV, conversie over meerdere vensters.','BrikPanel — Daily KPIs'=>'BrikPanel — Dagelijkse KPI\'s','last 90 days, one row per day.'=>'laatste 90 dagen, één rij per dag.','BrikPanel — Top Products'=>'BrikPanel — Topproducten','top 50 by units sold, last 90 days.'=>'top 50 op verkochte eenheden, laatste 90 dagen.','BrikPanel — Funnel'=>'BrikPanel — Funnel','daily visitor → checkout funnel.'=>'dagelijkse bezoeker → afrekenen-funnel.','Customers sync'=>'Klanten-synchronisatie','Each customer\'s metrics + RFM segment, refreshed after BrikPanel\'s nightly recompute. Tab is overwritten on every sync.'=>'Metrics van elke klant + RFM-segment, vernieuwd na de nachtelijke herberekening van BrikPanel. Het tabblad wordt bij elke synchronisatie overschreven.','Enable customers sync'=>'Klanten-synchronisatie inschakelen','Customer key and email are mandatory so rows can be de-duplicated.'=>'Klantsleutel en e-mail zijn verplicht zodat rijen kunnen worden ontdubbeld.','You do not have permission to export BrikPanel settings.'=>'U heeft geen toestemming om BrikPanel-instellingen te exporteren.','Could not encode BrikPanel settings as JSON.'=>'Kon BrikPanel-instellingen niet als JSON coderen.','You do not have permission to import BrikPanel settings.'=>'U heeft geen toestemming om BrikPanel-instellingen te importeren.','%1$d setting imported. %2$d unknown key skipped.'=>'%1$d instelling geïmporteerd. %2$d onbekende sleutel overgeslagen.' . "\0" . '%1$d instellingen geïmporteerd. %2$d onbekende sleutels overgeslagen.','Pick a BrikPanel JSON file before clicking Import.'=>'Kies een BrikPanel JSON-bestand voordat u op Importeren klikt.','That file is too large to be a BrikPanel settings export.'=>'Dat bestand is te groot om een BrikPanel-instellingenexport te zijn.','Could not read the uploaded file. Please try again.'=>'Kon het geüploade bestand niet lezen. Probeer het opnieuw.','That file is not a valid BrikPanel settings export.'=>'Dat bestand is geen geldige BrikPanel-instellingenexport.','The uploaded file did not contain any BrikPanel settings.'=>'Het geüploade bestand bevatte geen BrikPanel-instellingen.','Export settings'=>'Instellingen exporteren','Download every BrikPanel option as a single JSON file. Includes %d configuration keys: toggles, layout, accent color, sidebar order, dashboard order, notification preferences.'=>'Download elke BrikPanel-optie als één JSON-bestand. Bevat %d configuratiesleutels: schakelaars, lay-out, accentkleur, zijbalkvolgorde, dashboardvolgorde, meldingsvoorkeuren.','Download JSON file'=>'JSON-bestand downloaden','The brand logo image is not included — attachment IDs are tied to your media library and would point at a missing file on the target site. Re-pick the logo after importing.'=>'De merklogo-afbeelding is niet inbegrepen — bijlage-ID\'s zijn gekoppeld aan uw mediabibliotheek en zouden naar een ontbrekend bestand op de doelsite verwijzen. Kies het logo opnieuw na het importeren.','Import settings'=>'Instellingen importeren','Upload a JSON file exported from BrikPanel. Existing options with the same keys will be overwritten. Unknown keys are skipped — your store stays safe.'=>'Upload een JSON-bestand dat is geëxporteerd uit BrikPanel. Bestaande opties met dezelfde sleutels worden overschreven. Onbekende sleutels worden overgeslagen — uw winkel blijft veilig.','Drag a .json file here'=>'Sleep hier een .json-bestand','or click to browse'=>'of klik om te bladeren','Tip: export first if you want a quick rollback path.'=>'Tip: exporteer eerst als u een snel terugdraaipad wilt.','Logging in...'=>'Inloggen...','Log In'=>'Inloggen','An error occurred. Please try again.'=>'Er is een fout opgetreden. Probeer het opnieuw.','%s — Powered by WordPress'=>'%s — Powered by WordPress','Security check failed. Please refresh the page.'=>'Beveiligingscontrole mislukt. Vernieuw de pagina.','Please enter both username and password.'=>'Voer zowel gebruikersnaam als wachtwoord in.','Unknown username or email address.'=>'Onbekende gebruikersnaam of e-mailadres.','The password you entered is incorrect.'=>'Het wachtwoord dat u heeft ingevoerd is onjuist.','Please enter a username or email address.'=>'Voer een gebruikersnaam of e-mailadres in.','Please enter your password.'=>'Voer uw wachtwoord in.','Login failed. Please try again.'=>'Inloggen mislukt. Probeer het opnieuw.','Login successful! Redirecting...'=>'Inloggen geslaagd! Doorsturen...','Security check failed. Please reload and try again.'=>'Beveiligingscontrole mislukt. Herlaad de pagina en probeer het opnieuw.','You do not have permission to change this.'=>'U heeft geen toestemming om dit te wijzigen.','BrikPanel is on for the whole store. Switch off to use the classic WordPress admin.'=>'BrikPanel is aan voor de hele winkel. Schakel uit om het klassieke WordPress-beheer te gebruiken.','BrikPanel on'=>'BrikPanel aan','BrikPanel off'=>'BrikPanel uit','Switch BrikPanel off and use the classic WordPress admin'=>'Schakel BrikPanel uit en gebruik het klassieke WordPress-beheer','Switch the BrikPanel interface back on'=>'Schakel de BrikPanel-interface weer in','Could not change the BrikPanel switch. Please try again.'=>'Kon de BrikPanel-schakelaar niet wijzigen. Probeer het opnieuw.','Site management'=>'Sitebeheer','Default link'=>'Standaardlink','Home'=>'Home','Marketing'=>'Marketing','Payments'=>'Betalingen','Credit card'=>'Creditcard','Invoice'=>'Factuur','Tools'=>'Tools','Plugins'=>'Plugins','Users'=>'Gebruikers','Comments'=>'Reacties','Media'=>'Media','Pages'=>'Pagina\'s','Posts'=>'Berichten','Form'=>'Formulier','Snippets'=>'Snippets','More'=>'Meer','Sidebar navigation'=>'Zijbalknavigatie','Drag to reorder, toggle visibility, move items between sections, or add custom links.'=>'Sleep om volgorde te wijzigen, zichtbaarheid schakelen, items tussen secties verplaatsen of aangepaste links toevoegen.','Reset to defaults'=>'Terugzetten naar standaardwaarden','Item spacing'=>'Itemafstand','Spacing between menu items'=>'Afstand tussen menu-items','Compact'=>'Compact','Comfortable'=>'Comfortabel','Spacious'=>'Ruim','Sets the vertical gap between every sidebar item.'=>'Bepaalt de verticale ruimte tussen alle items in de zijbalk.','Section heading label'=>'Label van de sectiekop','Label for the Site management heading'=>'Label voor de kop Sitebeheer','Rename the “Site management” heading that separates your store items from the rest. Leave blank to keep the default.'=>'Hernoem de kop «Sitebeheer» die je winkelitems van de rest scheidt. Laat leeg om de standaard te behouden.','Who can see this item'=>'Wie dit item kan zien','Spacer'=>'Tussenruimte','Spacer style'=>'Stijl van de tussenruimte','Blank space'=>'Lege ruimte','Divider line'=>'Scheidingslijn','Remove spacer'=>'Tussenruimte verwijderen','Newly detected — not yet reviewed'=>'Nieuw gedetecteerd, nog niet beoordeeld','Visible in sidebar'=>'Zichtbaar in zijbalk','Edit link'=>'Link bewerken','Delete link'=>'Link verwijderen','Rename or change icon'=>'Naam of pictogram wijzigen','Manage submenu items'=>'Submenu-items beheren','Submenu items'=>'Submenu-items','Visible in submenu'=>'Zichtbaar in submenu','Add custom link'=>'Aangepaste link toevoegen','Add spacer'=>'Tussenruimte toevoegen','Top section'=>'Bovenste sectie','Items above the “Site management” heading.'=>'Items boven de kop “Sitebeheer”.','Items below the “Site management” heading. Leave empty to hide the heading.'=>'Items onder de kop “Sitebeheer”. Laat leeg om de kop te verbergen.','More menu'=>'Meer-menu','Items shown inside the More dropdown.'=>'Items getoond in het Meer-dropdownmenu.','Custom link'=>'Aangepaste link','Label'=>'Label','Customer support'=>'Klantenservice','URL'=>'URL','Icon'=>'Pictogram','Or paste a custom SVG icon'=>'Of plak een aangepast SVG-pictogram','Paste SVG code or a data:image/svg+xml;base64,… URI'=>'Plak SVG-code of een data:image/svg+xml;base64,… URI','Paste an SVG from Icons8, SVG Repo or anywhere — it overrides the icon chosen above. Leave empty to use the icon above.'=>'Plak een SVG van Icons8, SVG Repo of waar dan ook, het overschrijft het hierboven gekozen pictogram. Laat leeg om het pictogram hierboven te gebruiken.','Open in a new tab'=>'Openen in een nieuw tabblad','Use original'=>'Origineel gebruiken','Edit custom link'=>'Aangepaste link bewerken','Change icon'=>'Pictogram wijzigen','Edit menu item'=>'Menu-item bewerken','That SVG could not be read. Paste valid SVG code or a data:image/svg+xml URI.'=>'Die SVG kon niet worden gelezen. Plak geldige SVG-code of een data:image/svg+xml URI.','Reset sidebar navigation to its defaults? This clears all customizations and removes custom links.'=>'Zijbalknavigatie terugzetten naar de standaardwaarden? Dit wist alle aanpassingen en verwijdert aangepaste links.','Remove this custom link?'=>'Deze aangepaste link verwijderen?','Please enter a valid URL (starting with http:// or https://) or an admin path.'=>'Voer een geldige URL in (beginnend met http:// of https://) of een adminpad.','Please enter a label.'=>'Voer een label in.','Order statusReturn Draft'=>'Retourconcept','Order statusChange'=>'Wijzigen','orders bulk actionChange status to %s'=>'Status wijzigen naar %s','You are not allowed to do this.'=>'Je mag dit niet doen.','Select at least one status to import.'=>'Selecteer minstens één status om te importeren.','%d status imported.'=>'%d status geïmporteerd.' . "\0" . '%d statussen geïmporteerd.','Order statuses'=>'Orderstatussen','WooCommerce default (Pending payment)'=>'WooCommerce-standaard (Wachtend op betaling)','Create your own order statuses and choose where new orders begin. Use these for workflows WooCommerce does not cover out of the box, such as "Awaiting stock", "Packed" or "Ready for pickup". This applies to every order, whether it contains simple or variable products.'=>'Maak uw eigen orderstatussen en kies waar nieuwe bestellingen beginnen. Gebruik deze voor workflows die WooCommerce niet standaard dekt, zoals „Wacht op voorraad”, „Ingepakt” of „Klaar voor afhalen”. Dit geldt voor elke bestelling, of ze nu eenvoudige of variabele producten bevat.','Default status for new orders'=>'Standaardstatus voor nieuwe bestellingen','The status every new order starts in before payment is processed. Leave on the WooCommerce default unless you have a specific workflow that needs otherwise — changing this affects checkout and can interfere with payment gateways.'=>'De status waarin elke nieuwe bestelling begint voordat de betaling is verwerkt. Laat op de WooCommerce-standaard staan, tenzij u een specifieke workflow heeft die anders vereist, dit wijzigen beïnvloedt het afrekenen en kan betalingsgateways verstoren.','Import from another plugin'=>'Importeren uit een andere plugin','We found custom order statuses created outside BrikPanel. Adopt them here so you can safely deactivate the other plugin — your orders keep their status, colour and filters. This is the same for orders with simple or variable products.'=>'We hebben aangepaste bestelstatussen gevonden die buiten BrikPanel zijn aangemaakt. Neem ze hier over, zodat je de andere plugin veilig kunt uitschakelen: je bestellingen behouden hun status, kleur en filters. Dit werkt hetzelfde voor bestellingen met eenvoudige en met variabele producten.','Import selected'=>'Selectie importeren','%s order'=>'%s bestelling' . "\0" . '%s bestellingen','Currently provided by another active plugin.'=>'Wordt momenteel geleverd door een andere actieve plugin.','active plugin'=>'actieve plugin','Used by orders but no longer registered by any plugin — orders show the raw status key until you import it.'=>'Wordt gebruikt door bestellingen, maar niet meer geregistreerd door een plugin: bestellingen tonen de ruwe statussleutel totdat je hem importeert.','needs rescue'=>'moet worden gered','Imported statuses appear in the list below, where you can rename the colour or remove them. Only import statuses from a plugin you plan to remove — a status marked "active plugin" is still managed by that plugin.'=>'Geïmporteerde statussen verschijnen in de lijst hieronder, waar je ze kunt hernoemen, de kleur kunt wijzigen of ze kunt verwijderen. Importeer alleen statussen uit een plugin die je wilt verwijderen: een status met de markering "actieve plugin" wordt nog steeds door die plugin beheerd.','Your custom statuses'=>'Uw aangepaste statussen','Add as many as you need. Pick a colour so each one stands out in the orders list.'=>'Voeg er zoveel toe als u nodig heeft. Kies een kleur zodat elk opvalt in de bestellijst.','Add status'=>'Status toevoegen','No custom statuses yet. Click "Add status" to create your first one.'=>'Nog geen aangepaste statussen. Klik op „Status toevoegen” om uw eerste te maken.','Status name'=>'Statusnaam','Remove status'=>'Status verwijderen','Removing a status that orders already use will leave those orders showing the raw status key until you re-create it. Existing status keys cannot be renamed.'=>'Een status verwijderen die bestellingen al gebruiken, laat die bestellingen de ruwe statussleutel tonen totdat u hem opnieuw aanmaakt. Bestaande statussleutels kunnen niet worden hernoemd.','Remove this status? Orders already using it will show the raw status key until you re-create it.'=>'Deze status verwijderen? Bestellingen die hem al gebruiken, tonen de ruwe statussleutel totdat u hem opnieuw aanmaakt.','new'=>'nieuw','Import failed. Please try again.'=>'Importeren mislukt. Probeer het opnieuw.','Your order {order_number} is now {order_status}'=>'Je bestelling {order_number} is nu {order_status}','Your order status has changed'=>'De status van je bestelling is gewijzigd','Hi {customer_first_name},

This is a quick update on your order {order_number} placed on {order_date}. Its status is now: {order_status}.

{order_items}

Order total: {order_total}

You can view your order here: {order_view_url}

Thank you for shopping with {site_title}.'=>'Hallo {customer_first_name},

Dit is een korte update over je bestelling {order_number} van {order_date}. De status is nu: {order_status}.

{order_items}

Besteltotaal: {order_total}

Je kunt je bestelling hier bekijken: {order_view_url}

Bedankt voor je aankoop bij {site_title}.','New status name'=>'Naam van de nieuwe status','List of items'=>'Lijst met items','Order view link'=>'Link om de bestelling te bekijken','Customer first name'=>'Voornaam van de klant','Customer full name'=>'Volledige naam van de klant','Customer email'=>'E-mailadres van de klant','Store name'=>'Naam van de winkel','Status change emails'=>'E-mails bij statuswijziging','Send an email automatically when an order moves into one of your custom statuses. Each email is styled like your other WooCommerce emails and can use placeholders such as {order_number}.'=>'Stuur automatisch een e-mail wanneer een bestelling naar een van je aangepaste statussen gaat. Elke e-mail heeft dezelfde opmaak als je andere WooCommerce-e-mails en kan plaatshouders zoals {order_number} gebruiken.','Create a custom status above first, then set up its email here.'=>'Maak eerst hierboven een aangepaste status aan en stel hier daarna de bijbehorende e-mail in.','On'=>'Aan','Off'=>'Uit','Send to'=>'Verzenden naar','Store admin'=>'Winkelbeheerder','Extra recipients'=>'Extra ontvangers','name@example.com, warehouse@example.com'=>'naam@voorbeeld.com, magazijn@voorbeeld.com','Subject'=>'Onderwerp','Heading'=>'Kop','Message'=>'Bericht','Insert placeholder'=>'Plaatshouder invoegen','Additional details'=>'Aanvullende gegevens','No additional details for this order.'=>'Geen aanvullende gegevens voor deze bestelling.','Order custom fields'=>'Aangepaste ordervelden','Show a chosen list of order custom fields (extra checkout fields and other order meta) as a clean "Additional details" card on the order page. The card only appears for orders that actually have one of these fields filled in.'=>'Toon een gekozen lijst van aangepaste ordervelden (extra afrekenvelden en andere ordermeta) als een strakke kaart „Aanvullende gegevens” op de orderpagina. De kaart verschijnt alleen voor bestellingen waarbij een van deze velden daadwerkelijk is ingevuld.','Fields to display'=>'Weer te geven velden','Pick which order custom fields to show. The list is detected automatically from your existing orders. Leave empty to show none.'=>'Kies welke aangepaste ordervelden u wilt tonen. De lijst wordt automatisch gedetecteerd op basis van uw bestaande bestellingen. Laat leeg om er geen te tonen.','Additional fields (advanced)'=>'Aanvullende velden (geavanceerd)','Add custom fields by hand when a key is not in the list above, or to set a friendly label. One field per line, as the meta key, optionally followed by a vertical bar and a label. Example: _billing_vat_number | VAT number'=>'Voeg handmatig aangepaste velden toe wanneer een sleutel niet in de bovenstaande lijst staat, of om een leesbaar label in te stellen. Eén veld per regel, als de meta-sleutel, optioneel gevolgd door een verticale streep en een label. Voorbeeld: _billing_vat_number | Btw-nummer','WhatsApp'=>'WhatsApp','Message the customer on WhatsApp'=>'De klant een bericht sturen op WhatsApp','Message on WhatsApp'=>'Bericht sturen op WhatsApp','BrikPanel'=>'BrikPanel','Navigation'=>'Navigatie','Modern navigation'=>'Moderne navigatie','Replace the default WordPress admin menu with a modern, clean sidebar navigation'=>'Vervang het standaard WordPress-adminmenu door een moderne, schone zijbalknavigatie','Style the default menu'=>'Het standaardmenu stylen','When Modern navigation is off, give the standard WordPress admin menu the BrikPanel look. Turn this off to keep the original WordPress menu unchanged.'=>'Wanneer Moderne navigatie uit staat, geef het standaard WordPress-beheermenu de BrikPanel-look. Schakel dit uit om het originele WordPress-menu ongewijzigd te laten.','Hide new menu items by default'=>'Nieuwe menu-items standaard verbergen','When a newly installed plugin adds a sidebar menu item, keep it hidden until you review it in the editor below. Handy when you manage sites for clients and do not want new items to appear before you have checked them. Items you have already placed are unaffected.'=>'Wanneer een nieuw geïnstalleerde plugin een item aan de zijbalk toevoegt, blijft dat verborgen totdat je het in de editor hieronder hebt bekeken. Handig als je sites voor klanten beheert en niet wilt dat er nieuwe items verschijnen voordat je ze hebt gecontroleerd. Items die je al hebt geplaatst, blijven ongewijzigd.','Orders List'=>'Bestellijst','Enhanced orders page'=>'Verbeterde bestellingenpagina','Enhance the orders list page with modern search, filters, overview section, and styling'=>'Verbeter de bestellijstpagina met moderne zoek, filters, overzichtsectie en styling','Order Edit Page'=>'Bestelbewerkpagina','Modern order edit'=>'Moderne bestelbewerking','Clean up the order edit page — hide unnecessary metaboxes and apply modern styling'=>'Ruim de bestelbewerkpagina op — verberg onnodige metaboxen en pas moderne styling toe','Simplified product editor'=>'Vereenvoudigde producteditor','Replace the default WooCommerce product editor with a simplified, easy-to-use interface'=>'Vervang de standaard WooCommerce-producteditor door een vereenvoudigde, gebruiksvriendelijke interface','Product type selector'=>'Producttype-keuzemenu','Show a product type dropdown in the simplified editor so you can create subscription, variable subscription, bundle and other types registered by third-party plugins. When off, only simple and variable products can be created. Auto-enabled if a subscription/bookings/bundles plugin is active.'=>'Toon een producttype-dropdown in de vereenvoudigde editor zodat u abonnementen, variabele abonnementen, bundels en andere typen geregistreerd door externe plugins kunt aanmaken. Indien uit kunnen alleen eenvoudige en variabele producten worden aangemaakt. Automatisch ingeschakeld als een abonnementen-/boekingen-/bundelsplugin actief is.','Visible editor sections'=>'Zichtbare editor-secties','Toggle a section to show or hide it. Use the arrows to reorder — the product editor renders sections in the order shown here. Metaboxes registered by other plugins (Yoast SEO, Rank Math, All in One SEO, SEOPress, custom post types, etc.) appear in this list automatically, tagged "Plugin" — enable and position any you want to edit right inside the BrikPanel editor.'=>'Zet een sectie aan of uit om hem te tonen of te verbergen. Gebruik de pijlen om de volgorde te wijzigen: de producteditor toont de secties in de volgorde die je hier ziet. Metaboxen die door andere plugins zijn geregistreerd (Yoast SEO, Rank Math, All in One SEO, SEOPress, aangepaste berichttypen, enzovoort) verschijnen automatisch in deze lijst met de markering "Plugin": schakel de secties in en plaats de secties die je rechtstreeks in de BrikPanel-editor wilt bewerken.','Product publish scheduling'=>'Publicatie van producten inplannen','Add a "Scheduled" option to the status menu in the product editor so you can set a future date and time for a product to go live automatically. Works for simple and variable products.'=>'Voegt een optie "Ingepland" toe aan het statusmenu in de producteditor, zodat je een toekomstige datum en tijd kunt instellen waarop een product automatisch live gaat. Werkt voor eenvoudige en variabele producten.','Auto-include ACF field groups'=>'ACF-veldgroepen automatisch opnemen','Automatically render Advanced Custom Fields field groups whose Location Rules target products. When off, ACF field groups are hidden from the editor.'=>'Toon automatisch de veldgroepen van Advanced Custom Fields waarvan de locatieregels op producten gericht zijn. Als dit uitstaat, worden ACF-veldgroepen verborgen in de editor.','Additional product data sections'=>'Aanvullende productgegevenssecties','Pick which sections from WooCommerce\'s native "Product data" tabs (General, Inventory, Shipping, and custom tabs added by Subscriptions, Memberships, Bookings, swatches, SEO plugins…) should appear as "Additional product data" inside the BrikPanel editor. Leave empty to hide all — hidden by default.'=>'Kies welke secties van WooCommerce\'s native "Productgegevens"-tabbladen (Algemeen, Voorraad, Verzending en aangepaste tabbladen toegevoegd door Subscriptions, Memberships, Bookings, swatches, SEO-plugins…) moeten verschijnen als "Aanvullende productgegevens" in de BrikPanel-editor. Laat leeg om alles te verbergen — standaard verborgen.','Additional product data position'=>'Positie aanvullende productgegevens','Where the "Additional product data" card appears inside the BrikPanel product editor.'=>'Waar de kaart "Aanvullende productgegevens" verschijnt in de BrikPanel-producteditor.','Top — right under the product name'=>'Boven — direct onder de productnaam','Middle — between pricing and inventory'=>'Midden — tussen prijzen en voorraad','Bottom — end of the editor'=>'Onderaan — einde van de editor','Additional variation data sections'=>'Aanvullende variatiegegevenssecties','Pick which per-variation fields added by third-party plugins (pricing extensions, subscriptions, inventory add-ons…) should appear inside each variation row. Leave empty to hide all — hidden by default.'=>'Kies welke per-variatie-velden toegevoegd door externe plugins (prijsuitbreidingen, abonnementen, voorraad-add-ons…) moeten verschijnen in elke variatierij. Laat leeg om alles te verbergen — standaard verborgen.','Modern products list'=>'Moderne productenlijst','Replace the default products list with a modern, AJAX-powered interface with inline editing'=>'Vervang de standaardproductenlijst door een moderne, AJAX-aangedreven interface met inline bewerking','Quick Edit drawer fields'=>'Snelbewerking-laden velden','Pick which fields appear in the Quick Edit drawer and the order they render in. Toggle a field to show or hide it; use the arrows to reorder. "Simple only" fields are skipped automatically when editing variable products. The featured-product star toggle also controls the matching icons in the products list and the product editor header.'=>'Kies welke velden verschijnen in de Snelbewerking-lade en de volgorde waarin ze worden gerenderd. Schakel een veld om dit te tonen of te verbergen; gebruik de pijlen om de volgorde te wijzigen. "Alleen eenvoudig"-velden worden automatisch overgeslagen bij het bewerken van variabele producten. De schakelaar voor het uitgelichte-product-sterretje regelt ook de bijbehorende pictogrammen in de productenlijst en de header van de producteditor.','Open product in new tab'=>'Product openen in nieuw tabblad','When enabled, clicking a product name in the products list opens the edit page in a new browser tab.'=>'Indien ingeschakeld opent het klikken op een productnaam in de productenlijst de bewerkpagina in een nieuw browsertabblad.','Products per page'=>'Producten per pagina','Number of products to display per page in the products list'=>'Aantal producten dat per pagina in de productenlijst moet worden weergegeven','Categories per page'=>'Categorieën per pagina','Number of categories to display per page'=>'Aantal categorieën dat per pagina moet worden weergegeven','Backorder notification option'=>'Optie achterstandsmelding','Reveal a "Notify customer" choice under the stock status when "On backorder" is selected. Lets you allow backorders silently or with an order-note alert. Applies to simple products and variations.'=>'Toon een keuze "Klant op de hoogte stellen" onder de voorraadstatus wanneer "In achterstand" is geselecteerd. Hiermee kunt u achterstanden stil toestaan of met een melding via een bestelnotitie. Geldt voor eenvoudige producten en variaties.','Multiple images per variation'=>'Meerdere afbeeldingen per variatie','Allow each variation to have its own image gallery (multiple images), and swap the product gallery on the storefront when a variation is selected. When off, each variation is limited to a single image — the WooCommerce default. Existing extra variation images are kept in the database and will reappear if you re-enable this option.'=>'Sta toe dat elke variatie zijn eigen afbeeldingsgalerij heeft (meerdere afbeeldingen) en wissel de productgalerij in de winkel om wanneer een variatie wordt geselecteerd. Indien uit is elke variatie beperkt tot één afbeelding — de WooCommerce-standaard. Bestaande extra variatieafbeeldingen blijven in de database en verschijnen opnieuw als u deze optie opnieuw inschakelt.','Modern dashboard'=>'Modern dashboard','Replace the default WordPress dashboard with a modern, Shopify-inspired analytics dashboard'=>'Vervang het standaard WordPress-dashboard door een modern, Shopify-geïnspireerd analyticsdashboard','Dashboard top bar'=>'Dashboard-bovenbalk','Hide the WordPress admin bar on the BrikPanel dashboard and replace it with a BrikPanel-styled e-commerce top bar featuring live revenue, live visitors, global search, quick-create actions, and order notifications.'=>'Verberg de WordPress-adminbalk op het BrikPanel-dashboard en vervang deze door een BrikPanel-gestylde e-commerce bovenbalk met live omzet, live bezoekers, globaal zoeken, snel-aanmaken-acties en bestelmeldingen.','Top bar items'=>'Items in de bovenbalk','Choose which controls appear in the BrikPanel top bar. Turn a control off to hide it from the bar.'=>'Kies welke besturingselementen in de BrikPanel-bovenbalk verschijnen. Schakel een element uit om het uit de balk te verbergen.','Include WordPress dashboard widgets'=>'WordPress-dashboardwidgets opnemen','Pick which WordPress dashboard widgets (e.g. At a Glance, Activity, Fail2Ban log) should also appear inside the BrikPanel dashboard, styled to match. Widgets are arranged in a responsive 3-column grid.'=>'Kies welke WordPress-dashboardwidgets (bijv. In een oogopslag, Activiteit, Fail2Ban-logboek) ook in het BrikPanel-dashboard moeten verschijnen, in dezelfde stijl. Widgets worden gerangschikt in een responsief raster met 3 kolommen.','Widget access'=>'Widgettoegang','Choose who can see each embedded WordPress dashboard widget. Use this to keep sensitive widgets like "Site Health Status" limited to administrators or specific roles. Administrators always see every widget.'=>'Kies wie elke ingesloten WordPress-dashboardwidget kan zien. Gebruik dit om gevoelige widgets zoals "Sitediagnose" te beperken tot beheerders of specifieke rollen. Beheerders zien altijd elke widget.','Dashboard sections'=>'Dashboardsecties','Toggle a section to show or hide it. Use the arrows to reorder — the dashboard renders sections in the order shown here. Hidden sections skip rendering entirely, so their data is not fetched.'=>'Schakel een sectie om deze te tonen of te verbergen. Gebruik de pijlen om de volgorde te wijzigen — het dashboard rendert secties in de hier getoonde volgorde. Verborgen secties slaan het renderen volledig over, dus hun gegevens worden niet opgehaald.','Profit section fields'=>'Velden van de sectie Winst','Choose which fields appear in the Profit section. Revenue and Net profit are always shown. Hiding a field only removes it from view — it is still factored into Net profit where it is a real cost, so the figure stays accurate.'=>'Kies welke velden in de sectie Winst verschijnen. Omzet en Nettowinst worden altijd getoond. Een veld verbergen haalt het alleen uit beeld, het wordt nog steeds meegerekend in de nettowinst waar het een echte kost is, zodat het cijfer nauwkeurig blijft.','Decide which order statuses your analytics count. This drives every figure: Revenue, Orders, Average Order Value, Profit, Customer Lifetime Value and the order-rate breakdown. If you use a shipment-tracking or returns plugin that adds custom statuses (for example "Partially shipped", "Delivered" or "Partially refunded"), add them here so those orders stop being left out of your numbers.'=>'Bepaal welke orderstatussen uw analyses meetellen. Dit bepaalt elk cijfer: Omzet, Bestellingen, Gemiddelde orderwaarde, Winst, Customer Lifetime Value en de uitsplitsing per orderverhouding. Als u een plugin voor zendingvolging of retouren gebruikt die aangepaste statussen toevoegt (bijvoorbeeld „Gedeeltelijk verzonden”, „Geleverd” of „Gedeeltelijk terugbetaald”), voeg ze hier toe zodat die bestellingen niet langer uit uw cijfers worden weggelaten.','Statuses counted as valid sales'=>'Statussen die als geldige verkopen tellen','Orders in these statuses are counted as real, completed sales across Revenue, Orders, AOV, Profit and Customer Lifetime Value. Defaults to Processing and Completed, which is what WooCommerce itself treats as paid. Leave empty to keep the default.'=>'Bestellingen in deze statussen worden geteld als echte, voltooide verkopen in Omzet, Bestellingen, AOV, Winst en Customer Lifetime Value. Standaard In behandeling en Voltooid, wat WooCommerce zelf als betaald beschouwt. Laat leeg om de standaard te behouden.','Statuses counted as refunds'=>'Statussen die als terugbetalingen tellen','Orders in these statuses are treated as refunds in the returns and refund-rate figures, and still count toward Customer Lifetime Value (the customer did buy). Defaults to the WooCommerce Refunded status. Leave empty to keep the default.'=>'Bestellingen in deze statussen worden behandeld als terugbetalingen in de cijfers voor retouren en terugbetalingspercentage, en tellen nog steeds mee voor Customer Lifetime Value (de klant heeft wel gekocht). Standaard de WooCommerce-status Terugbetaald. Laat leeg om de standaard te behouden.','Modern coupons page settings, plus optional usage restriction fields for power users migrating from the default WooCommerce editor.'=>'Instellingen voor de moderne kortingsbonnenpagina, plus optionele gebruiksbeperkingsvelden voor power users die migreren vanuit de standaard WooCommerce-editor.','Modern coupons page'=>'Moderne kortingsbonnenpagina','Replace the default coupons list with a modern, AJAX-powered interface'=>'Vervang de standaard kortingsbonlijst door een moderne, AJAX-aangedreven interface','Restrict to specific products'=>'Beperken tot specifieke producten','Show a "Products" picker so you can limit the coupon to a hand-picked product list.'=>'Toon een "Producten"-picker zodat u de kortingsbon kunt beperken tot een handmatig gekozen productlijst.','Exclude specific products'=>'Specifieke producten uitsluiten','Show an "Exclude products" picker so you can disallow specific products even when the rest of the cart qualifies.'=>'Toon een "Producten uitsluiten"-picker zodat u specifieke producten kunt weigeren, zelfs wanneer de rest van de winkelwagen in aanmerking komt.','Restrict to product categories'=>'Beperken tot productcategorieën','Show a "Product categories" picker so the coupon only applies to items in the selected categories.'=>'Toon een "Productcategorieën"-picker zodat de kortingsbon alleen geldt voor artikelen in de geselecteerde categorieën.','Exclude product categories'=>'Productcategorieën uitsluiten','Show an "Exclude categories" picker so the coupon never applies to items in the selected categories.'=>'Toon een "Categorieën uitsluiten"-picker zodat de kortingsbon nooit geldt voor artikelen in de geselecteerde categorieën.','Allowed email addresses'=>'Toegestane e-mailadressen','Show an "Allowed emails" field that whitelists which billing email addresses can use the coupon.'=>'Toon een veld "Toegestane e-mails" dat aangeeft welke factuur-e-mailadressen de kortingsbon mogen gebruiken.','Show a "Limit usage to X items" field that caps how many matching items the discount applies to per cart.'=>'Toon een veld "Beperk gebruik tot X artikelen" dat begrenst op hoeveel overeenkomende artikelen per winkelwagen de korting van toepassing is.','Login Page'=>'Inlogpagina','Modern login page'=>'Moderne inlogpagina','Replace the default WordPress login page with a clean, modern design and AJAX-powered authentication'=>'Vervang de standaard WordPress-inlogpagina door een schoon, modern ontwerp en AJAX-aangedreven authenticatie','Hide "Powered by WordPress" credit'=>'Verberg "Powered by WordPress"-vermelding','Remove the "— Powered by WordPress" text below the login card'=>'Verwijder de tekst "— Powered by WordPress" onder de inlogkaart','Force native login submission'=>'Native inlogverzending forceren','Recommended. Submits the login form to wp-login.php natively while keeping the modern design, so any 2FA, SSO, or custom authentication plugin (Wordfence Login Security, Two Factor, WP 2FA, miniOrange, Solid Security, Duo, Rublon, etc.) works as expected. Disable only if you rely on the AJAX login endpoint and are certain no authentication plugin alters the login flow.'=>'Aanbevolen. Verzendt het inlogformulier native naar wp-login.php terwijl het moderne ontwerp behouden blijft, zodat elke 2FA-, SSO- of aangepaste authenticatieplugin (Wordfence Login Security, Two Factor, WP 2FA, miniOrange, Solid Security, Duo, Rublon, enz.) werkt zoals verwacht. Schakel alleen uit als u op de AJAX-inlogendpoint vertrouwt en zeker weet dat geen authenticatieplugin de inlogflow wijzigt.','Admin notices'=>'Admin-meldingen','Hide third-party admin notices'=>'Externe admin-meldingen verbergen','Suppress admin notices from other plugins and themes. BrikPanel\'s own notices always remain visible. Turn this off to restore the default WordPress behaviour.'=>'Onderdruk admin-meldingen van andere plugins en thema\'s. De eigen meldingen van BrikPanel blijven altijd zichtbaar. Schakel dit uit om het standaard WordPress-gedrag te herstellen.','Also hide error notices'=>'Ook foutmeldingen verbergen','By default red error notices stay on screen, since they usually mean something is broken. Enable this to tuck them into the notifications bell too. Only applies while "Hide third-party admin notices" is on.'=>'Standaard blijven rode foutmeldingen op het scherm staan, omdat ze meestal betekenen dat er iets kapot is. Schakel dit in om ze ook in de meldingsbel op te bergen. Geldt alleen wanneer „Beheermeldingen van derden verbergen” aan staat.','Real-time alerts when a new paid order arrives while you have the WordPress admin open.'=>'Real-time meldingen wanneer een nieuwe betaalde bestelling binnenkomt terwijl u de WordPress-admin geopend heeft.','Show new order popup'=>'Pop-up voor nieuwe bestelling tonen','Display a slide-in card in the corner of the admin whenever a new paid order arrives.'=>'Toon een inschuivende kaart in de hoek van de admin telkens wanneer een nieuwe betaalde bestelling binnenkomt.','Play notification sound'=>'Meldingsgeluid afspelen','Play a short chime to alert you of new paid orders. Some browsers require an interaction with the page before audio can play automatically.'=>'Speel een kort belletje af om u op de hoogte te stellen van nieuwe betaalde bestellingen. Sommige browsers vereisen een interactie met de pagina voordat audio automatisch kan worden afgespeeld.','Confetti celebration'=>'Confettiviering','Briefly burst confetti across the screen to celebrate each new order.'=>'Laat kort confetti over het scherm springen om elke nieuwe bestelling te vieren.','Sound volume'=>'Geluidsvolume','Volume of the new-order chime, from 0 (silent) to 100 (loud).'=>'Volume van het nieuwe-bestelling-belletje, van 0 (stil) tot 100 (hard).','Polling interval (seconds)'=>'Polling-interval (seconden)','How often the admin checks for new orders. Lower values feel more instant; higher values reduce server load. Min 10, max 300.'=>'Hoe vaak de admin controleert op nieuwe bestellingen. Lagere waarden voelen directer aan; hogere waarden verminderen de serverbelasting. Min 10, max 300.','Developers'=>'Ontwikkelaars','Build on top of BrikPanel with public hooks and filters. The docs below are generated from the plugin source.'=>'Bouw bovenop BrikPanel met publieke hooks en filters. De documentatie hieronder wordt gegenereerd uit de pluginbron.','Login page'=>'Inlogpagina','Notifications'=>'Meldingen','Import / Export'=>'Importeren / Exporteren','Interface'=>'Interface','Store'=>'Winkel','System'=>'Systeem','BrikPanel settings sections'=>'Secties van BrikPanel-instellingen','Search settings'=>'Instellingen zoeken','No settings found.'=>'Geen instellingen gevonden.','BrikPanel settings saved.'=>'BrikPanel-instellingen opgeslagen.','Payment Method'=>'Betaalmethode','Tax Total'=>'Belastingtotaal','All shipping methods'=>'Alle verzendmethoden','Order not found.'=>'Bestelling niet gevonden.','Invalid status.'=>'Ongeldige status.','No image'=>'Geen afbeelding','Category not found.'=>'Categorie niet gevonden.','Parent category not found.'=>'Bovenliggende categorie niet gevonden.','Cannot set a child category as parent.'=>'Kan een subcategorie niet als bovenliggende instellen.','None (top level)'=>'Geen (hoogste niveau)','"%1$s" moved under "%2$s"'=>'"%1$s" verplaatst onder "%2$s"','Invalid product.'=>'Ongeldig product.','Product Editor'=>'Producteditor','Product not found.'=>'Product niet gevonden.','Text style'=>'Tekststijl','Paragraph'=>'Paragraaf','Heading 1'=>'Kop 1','Heading 2'=>'Kop 2','Heading 3'=>'Kop 3','Heading 4'=>'Kop 4','Heading 5'=>'Kop 5','Quote'=>'Citaat','Bold'=>'Vet','Italic'=>'Cursief','Bullet list'=>'Opsommingslijst','Numbered list'=>'Genummerde lijst','Align left'=>'Links uitlijnen','Align center'=>'Centreren','Align right'=>'Rechts uitlijnen','Text color'=>'Tekstkleur','Insert link'=>'Link invoegen','Remove link'=>'Link verwijderen','Insert image'=>'Afbeelding invoegen','Clear formatting'=>'Opmaak wissen','HTML source'=>'HTML-bron','Standard'=>'Standaard','Same as parent'=>'Hetzelfde als bovenliggend','No shipping class'=>'Geen verzendklasse','Edit product'=>'Product bewerken','Add product'=>'Product toevoegen','Additional product data'=>'Aanvullende productgegevens','More actions'=>'Meer acties','View product'=>'Product bekijken','Duplicate'=>'Dupliceren','Add new'=>'Nieuwe toevoegen','Featured'=>'Uitgelicht','Mark as featured'=>'Markeren als uitgelicht','Scheduled'=>'Gepland','Private'=>'Privé','Password protected'=>'Beveiligd met wachtwoord','Visible to everyone on the storefront'=>'Zichtbaar voor iedereen in de winkel','Publishes automatically on a future date'=>'Wordt automatisch op een toekomstige datum gepubliceerd','Not visible on the storefront'=>'Niet zichtbaar in de winkel','Visible only to admins and editors'=>'Alleen zichtbaar voor admins en redacteuren','Visitors must enter a password to view'=>'Bezoekers moeten een wachtwoord invoeren om te bekijken','Password...'=>'Wachtwoord...','Publish date and time'=>'Publicatiedatum en -tijd','Shop & search'=>'Winkel & zoeken','Shop only'=>'Alleen winkel','Search only'=>'Alleen zoeken','Hidden'=>'Verborgen','Catalog visibility'=>'Catalogus-zichtbaarheid','Schedule'=>'Inplannen','Update'=>'Bijwerken','E.g.: Cotton White T-Shirt - M Size'=>'Bijv.: Wit katoenen T-shirt - Maat M','Product type'=>'Producttype','Pick how this product is sold. Third-party plugins (subscriptions, bookings, bundles) register their own types here.'=>'Kies hoe dit product wordt verkocht. Externe plugins (abonnementen, boekingen, bundels) registreren hier hun eigen typen.','Product images'=>'Productafbeeldingen','Drag & drop images here'=>'Sleep afbeeldingen hier naartoe','Add images'=>'Afbeeldingen toevoegen','Permalink (URL slug)'=>'Permalink (URL-slug)','auto-generated-from-name'=>'automatisch-gegenereerd-uit-naam','The last part of the product URL. Leave blank to generate it automatically from the product name.'=>'Het laatste deel van de product-URL. Laat leeg om het automatisch uit de productnaam te genereren.','Variable product'=>'Variabel product','Has options buyers choose from, like size or color.'=>'Heeft opties waaruit kopers kiezen, zoals maat of kleur.','product editor attribute section headingAttributes'=>'Attributen','Add attributes, then switch on “Use for variations” for the ones buyers pick (Size, Color). Others stay as specs shown on the product page.'=>'Voeg attributen toe en zet daarna «Gebruiken voor variaties» aan voor de attributen waaruit kopers kiezen (maat, kleur). De rest blijft specificaties die op de productpagina worden getoond.','Specs that appear on the product page (e.g. Brand, Material).'=>'Specificaties die op de productpagina verschijnen (bijv. merk, materiaal).','Size + Color'=>'Maat + Kleur','Size and color combinations'=>'Maat- en kleurcombinaties','Use existing or create new attributes'=>'Bestaande gebruiken of nieuwe attributen aanmaken','Select existing attribute…'=>'Bestaand attribuut selecteren…','Search attributes…'=>'Attributen zoeken…','No matching attributes'=>'Geen overeenkomende attributen','or create new'=>'of nieuw aanmaken','Attribute name (e.g.: Size, Brand)'=>'Naam van het attribuut (bijv.: maat, merk)','Add'=>'Toevoegen','Quick add:'=>'Snel toevoegen:','+ Size & Color'=>'+ Maat en kleur','Generate variations'=>'Variaties genereren','Attributes changed since you generated. Click Generate variations to refresh the list.'=>'De attributen zijn gewijzigd sinds het genereren. Klik op Variaties genereren om de lijst te vernieuwen.','Apply to all variations'=>'Toepassen op alle variaties','Sale Price'=>'Aanbiedingsprijs','No change'=>'Geen wijziging','Set active'=>'Op actief zetten','Set inactive'=>'Op inactief zetten','Variation'=>'Variatie','Sale start'=>'Aanbieding start','Sale end'=>'Aanbieding einde','Track stock quantity for this variation'=>'Voorraadaantal voor deze variatie bijhouden','Track'=>'Bijhouden','COGS'=>'COGS','Supplier'=>'Leverancier','GTIN'=>'GTIN','Tax class'=>'Belastingklasse','Shipping class'=>'Verzendklasse','Sale start date'=>'Aanbieding-startdatum','YYYY-MM-DD (optional)'=>'JJJJ-MM-DD (optioneel)','Sale end date'=>'Aanbieding-einddatum','Schedule your sale in advance — leave the dates empty to start it immediately or keep it running indefinitely.'=>'Plan uw aanbieding van tevoren — laat de datums leeg om deze direct te starten of onbeperkt te laten lopen.','— None —'=>'— Geen —','Supplier SKU'=>'Leverancier-SKU','The supplier\'s product code. Optional — used by stock orders to match this product on incoming POs.'=>'De productcode van de leverancier. Optioneel — gebruikt door voorraadbestellingen om dit product te matchen met inkomende PO\'s.','Optional'=>'Optioneel','What this product costs you, and where you buy it from. Used in profit calculations and stock orders.'=>'Wat dit product u kost en waar u het koopt. Gebruikt in winstberekeningen en voorraadbestellingen.','The cost you pay for this product. Used to calculate profit margins.'=>'De kosten die u voor dit product betaalt. Gebruikt om winstmarges te berekenen.','Track quantity'=>'Aantal bijhouden','Manage stock at product level. Turn off to simply mark the product in or out of stock.'=>'Beheer de voorraad op productniveau. Schakel uit om het product simpelweg op voorraad of niet op voorraad te markeren.','Stock quantity'=>'Voorraadaantal','Allow backorders?'=>'Nabestellingen toestaan?','Do not allow'=>'Niet toestaan','Allow, but notify customer'=>'Toestaan, maar klant op de hoogte stellen','Allow'=>'Toestaan','In stock'=>'Op voorraad','On backorder'=>'In achterstand','Important for marketplace synchronization. Should match your Trendyol/Hepsiburada product code.'=>'Belangrijk voor marketplace-synchronisatie. Moet overeenkomen met uw Trendyol/Hepsiburada-productcode.','e.g.: TSH-001'=>'bijv.: TSH-001','Backorder behavior'=>'Achterstand-gedrag','Allow without notification'=>'Toestaan zonder melding','Allow and notify customer'=>'Toestaan en klant op de hoogte stellen','Notification adds a customer-visible note to backorder line items at checkout.'=>'Melding voegt een voor de klant zichtbare notitie toe aan achterstandsregelitems tijdens het afrekenen.','GTIN, UPC, EAN, or ISBN'=>'GTIN, UPC, EAN of ISBN','The global product barcode. Used by Google Shopping and marketplace feeds. Leave empty if you do not have one.'=>'De globale productbarcode. Gebruikt door Google Shopping en marketplace-feeds. Laat leeg als u er geen heeft.','e.g.: 0012345678905'=>'bijv.: 0012345678905','Tax status'=>'Belastingstatus','Taxable'=>'Belastbaar','Shipping only'=>'Alleen verzending','None'=>'Geen','Variable products: each variation can override the tax class from the variations table.'=>'Variabele producten: elke variatie kan de belastingklasse overschrijven vanuit de variatietabel.','Sold individually'=>'Individueel verkocht','Limit purchases to one of this product per order.'=>'Beperk aankopen tot één van dit product per bestelling.','Upsells'=>'Upsells','Products promoted on the product page as a higher-value alternative.'=>'Producten die op de productpagina worden gepromoot als alternatief van hogere waarde.','Search products...'=>'Producten zoeken...','Cross-sells'=>'Cross-sells','Products promoted in the cart alongside this one.'=>'Producten die in de winkelwagen naast deze worden gepromoot.','Purchase note'=>'Aankoopnotitie','Note sent to the customer after they buy this product.'=>'Notitie die naar de klant wordt verzonden nadat zij dit product hebben gekocht.','Enable reviews'=>'Reviews inschakelen','Allow customers to leave reviews on this product.'=>'Sta klanten toe reviews achter te laten over dit product.','Menu order'=>'Menu-volgorde','Category'=>'Categorie','Search categories...'=>'Categorieën zoeken...','Primary category'=>'Hoofdcategorie','None (will disable this feature)'=>'Geen (schakelt deze functie uit)','The category used in the %category% permalink and breadcrumbs when a product has several categories.'=>'De categorie die wordt gebruikt in de permalink %category% en in de kruimelpaden wanneer een product tot meerdere categorieën behoort.','+ Add new category'=>'+ Nieuwe categorie toevoegen','Category name'=>'Categorienaam','— No parent —'=>'— Geen bovenliggende —','Brand'=>'Merk','Search brands...'=>'Merken zoeken...','+ Add new brand'=>'+ Nieuw merk toevoegen','Brand name'=>'Merknaam','Tags'=>'Tags','Type and press Enter to add a tag...'=>'Typ en druk op Enter om een tag toe te voegen...','Virtual (no shipping)'=>'Virtueel (geen verzending)','Service or intangible product — no physical shipping.'=>'Service of immaterieel product — geen fysieke verzending.','Digital (downloadable)'=>'Digitaal (downloadbaar)','Customers receive download links after purchase.'=>'Klanten ontvangen downloadlinks na aankoop.','Add downloadable file'=>'Downloadbaar bestand toevoegen','Brief product summary...'=>'Korte productsamenvatting...','Product description'=>'Productbeschrijving','Shipping weight'=>'Verzendgewicht','Shipping dimensions'=>'Verzendafmetingen','Length'=>'Lengte','Width'=>'Breedte','Height'=>'Hoogte','Shipping classes let certain shipping methods group similar products together. Variable products: each variation can override this from the variations table.'=>'Verzendklassen laten bepaalde verzendmethoden vergelijkbare producten groeperen. Variabele producten: elke variatie kan dit overschrijven vanuit de variatietabel.','SEO'=>'SEO','Product title'=>'Producttitel','SEO title'=>'SEO-titel','Leave empty to use product name'=>'Laat leeg om de productnaam te gebruiken','Meta description'=>'Meta-beschrijving','Brief description for search engines...'=>'Korte beschrijving voor zoekmachines...','Focus keyword'=>'Focuszoekwoord','e.g. cotton t-shirt'=>'bijv. katoenen t-shirt','Canonical URL'=>'Canonieke URL','Defaults to product permalink'=>'Standaard de permalink van het product','Hide from search engines'=>'Verbergen voor zoekmachines','Adds noindex — the product stays accessible but search engines will not list it.'=>'Voegt noindex toe — het product blijft toegankelijk maar zoekmachines vermelden het niet.','These fields are saved to %s, plus Yoast SEO, Rank Math, All in One SEO and SEOPress, so switching SEO plugins never loses your work.'=>'Deze velden worden opgeslagen in %s, plus Yoast SEO, Rank Math, All in One SEO en SEOPress, zodat het wisselen van SEO-plugin nooit uw werk verliest.','These fields are saved to Yoast SEO, Rank Math, All in One SEO and SEOPress simultaneously, so switching SEO plugins never loses your work.'=>'Deze velden worden tegelijk opgeslagen in Yoast SEO, Rank Math, All in One SEO en SEOPress, dus het wisselen van SEO-plugins gaat nooit ten koste van uw werk.','SEO analysis'=>'SEO-analyse','Re-analyze'=>'Opnieuw analyseren','Metabox failed to load.'=>'Metabox kon niet worden geladen.','Yoast SEO'=>'Yoast SEO','Rank Math SEO'=>'Rank Math SEO','All in One SEO'=>'All in One SEO','SEOPress'=>'SEOPress','SureRank'=>'SureRank','SmartCrawl'=>'SmartCrawl','No focus keyword set. Add one to analyze the title, description, URL and content.'=>'Geen focuszoekwoord ingesteld. Voeg er een toe om de titel, beschrijving, URL en inhoud te analyseren.','Suggestion'=>'Suggestie','Passed'=>'Geslaagd','%d critical'=>'%d kritiek' . "\0" . '%d kritiek','%d warning'=>'%d waarschuwing' . "\0" . '%d waarschuwingen','%d suggestion'=>'%d suggestie' . "\0" . '%d suggesties','%d passed'=>'%d geslaagd' . "\0" . '%d geslaagd','Page checks'=>'Paginacontroles','Keyword checks'=>'Zoekwoordcontroles','SEO title length is within the recommended range'=>'De lengte van de SEO-titel ligt binnen het aanbevolen bereik','Meta description length is within the recommended range'=>'De lengte van de metabeschrijving ligt binnen het aanbevolen bereik','Meta description is hand-written, not auto-generated'=>'De metabeschrijving is handgeschreven, niet automatisch gegenereerd','URL slug uses hyphens instead of underscores'=>'De URL-slug gebruikt koppeltekens in plaats van underscores','Focus keyword appears in the SEO title'=>'Het focuszoekwoord komt voor in de SEO-titel','Focus keyword appears in the meta description'=>'Het focuszoekwoord komt voor in de metabeschrijving','Focus keyword appears in the URL slug'=>'Het focuszoekwoord komt voor in de URL-slug','Focus keyword does not consist only of stop words'=>'Het focuszoekwoord bestaat niet alleen uit stopwoorden','Focus keyword has not been used on another product'=>'Het focuszoekwoord is niet op een ander product gebruikt','Secondary keyword appears in the SEO title'=>'Het secundaire zoekwoord komt voor in de SEO-titel','Content is long enough'=>'De inhoud is lang genoeg','Content contains at least one link'=>'De inhoud bevat ten minste één li